@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:ital,wght@0,500;0,600;0,700;0,800;0,900;1,700;1,800&family=Manrope:wght@400;500;600;700;800&display=swap');

:root {
  --ink: #f5f1e8;
  --muted: rgba(245, 241, 232, 0.62);
  --dim: rgba(245, 241, 232, 0.32);
  --line: rgba(255, 255, 255, 0.14);
  --panel: rgba(11, 13, 18, 0.66);
  --panel-solid: #0b0d12;
  --accent: #ff5a2a;
  --accent-2: #ffbe3d;
  --cyan: #6de7ff;
  --lime: #c8ff45;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --display: 'Barlow Condensed', 'Arial Narrow', 'Helvetica Neue', sans-serif;
  --body: 'Manrope', 'Helvetica Neue', Arial, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: #080a0e;
  color: var(--ink);
  font-family: var(--body);
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
  user-select: none;
}

button, input, select { font: inherit; }
button { color: inherit; }
button:focus-visible, [role='button']:focus-visible { outline: 2px solid var(--accent-2); outline-offset: 4px; }

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: #080a0e;
  touch-action: none;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
}

.vignette, .grain, .fade-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.vignette {
  background:
    radial-gradient(ellipse at 50% 45%, transparent 42%, rgba(2, 4, 8, 0.28) 76%, rgba(2, 4, 8, 0.72) 110%),
    linear-gradient(180deg, rgba(5, 7, 11, 0.24), transparent 26%, transparent 72%, rgba(5, 7, 11, 0.35));
  z-index: 2;
}

.grain {
  z-index: 3;
  opacity: 0.15;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 220 220' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.86' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.52'/%3E%3C/svg%3E");
  mix-blend-mode: soft-light;
}

.fade-layer {
  z-index: 90;
  background: #06080b;
  opacity: 0;
  transition: opacity 0.45s ease;
}
.fade-layer.show { opacity: 1; }

.screen { position: absolute; inset: 0; z-index: 10; }
.is-hidden { display: none !important; }
.hidden { opacity: 0; pointer-events: none; }

.eyebrow {
  font-family: var(--body);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.2em;
  color: var(--accent-2);
  text-transform: uppercase;
}

kbd {
  display: inline-block;
  padding: 2px 6px;
  margin: 0 2px;
  border: 1px solid rgba(255,255,255,.22);
  border-bottom-color: rgba(255,255,255,.35);
  border-radius: 3px;
  background: rgba(255,255,255,.06);
  color: rgba(255,255,255,.78);
