    radial-gradient(circle at 72% 36%, rgba(255, 109, 50, .13), transparent 28%),
    radial-gradient(circle at 24% 70%, rgba(62, 122, 255, .1), transparent 32%),
    #080a0e;
  transition: opacity .6s ease, visibility .6s;
}
.loading-screen.done { opacity: 0; visibility: hidden; }

.loading-mark, .brand-mark {
  display: grid;
  place-items: center;
