.season b { color: var(--accent); }

.hero-copy { position: absolute; top: 24%; left: clamp(26px, 5.4vw, 94px); max-width: 600px; pointer-events: none; }
.hero-copy .eyebrow { display: inline-flex; align-items: center; gap: 12px; }
.hero-copy .eyebrow::before { content: ''; width: 38px; height: 1px; background: var(--accent); }
.hero-copy h1 {
  margin: 12px 0 12px;
