.hero-copy p { max-width: 390px; margin: 18px 0 20px; color: rgba(255,255,255,.65); font-size: 13px; line-height: 1.6; font-weight: 500; }
.hero-tags { display: flex; gap: 8px; }
.hero-tags span { padding: 6px 9px; border: 1px solid rgba(255,255,255,.15); background: rgba(8,10,14,.25); color: rgba(255,255,255,.52); font-size: 8px; font-weight: 800; letter-spacing: .15em; }

