}
.cta::after { content: ''; position: absolute; inset: 0; background: linear-gradient(105deg, transparent 30%, rgba(255,255,255,.42), transparent 62%); transform: translateX(-120%); transition: transform .55s ease; }
.cta:hover { filter: brightness(1.08); transform: translateY(-1px); }
.cta:hover::after { transform: translateX(120%); }
.cta b { font-family: var(--display); font-size: 24px; font-weight: 500; line-height: 1; }
.panel-actions .cta { flex: 1; }
.ghost-button {
  min-height: 52px;
  padding: 0 16px;
  border: 1px solid rgba(255,255,255,.2);
  background: rgba(255,255,255,.035);
