.menu-footer { position: absolute; left: clamp(26px, 4vw, 72px); bottom: calc(27px + var(--safe-bottom)); display: flex; gap: 22px; color: rgba(255,255,255,.35); font-size: 8px; font-weight: 700; letter-spacing: .08em; }
.sound-toggle { position: absolute; right: clamp(26px, 4vw, 72px); bottom: calc(30px + var(--safe-bottom)); display: flex; align-items: center; gap: 9px; font-size: 8px; font-weight: 800; letter-spacing: .13em; color: rgba(255,255,255,.48); cursor: pointer; }
