/* ---------- HUD ---------- */
.hud { pointer-events: none; z-index: 15; }
.hud button { pointer-events: auto; }
.hud-top-left { position: absolute; top: calc(24px + var(--safe-top)); left: clamp(20px, 3vw, 46px); }
.event-chip { display: flex; align-items: center; gap: 11px; padding: 10px 14px 10px 11px; border-left: 2px solid var(--accent); background: linear-gradient(90deg, rgba(8,10,14,.72), rgba(8,10,14,.1)); }
.pulse-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 12px var(--accent); animation: blink 1.4s infinite; }
.event-chip small { display: block; font-size: 7px; font-weight: 800; letter-spacing: .2em; color: var(--accent-2); }
.event-chip strong { display: block; margin-top: 2px; font-family: var(--display); font-size: 18px; font-weight: 700; letter-spacing: .07em; }
.xp-line { display: flex; align-items: center; gap: 8px; margin-top: 11px; padding-left: 2px; }
.xp-line span { font-family: var(--display); font-size: 12px; font-weight: 700; letter-spacing: .08em; color: var(--accent-2); }
.xp-line i { display: block; width: 112px; height: 2px; background: rgba(255,255,255,.14); }
.xp-line i b { display: block; height: 100%; background: var(--accent-2); }
.xp-line em { font-size: 7px; font-style: normal; font-weight: 700; letter-spacing: .08em; color: rgba(255,255,255,.4); }

.hud-top-center { position: absolute; top: calc(24px + var(--safe-top)); left: 50%; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 8px; }
.race-clock { min-width: 224px; padding: 10px 18px 11px; text-align: center; border-top: 1px solid rgba(255,255,255,.18); background: linear-gradient(180deg, rgba(8,10,14,.68), rgba(8,10,14,.14)); }
.race-clock span { display: block; font-size: 7px; font-weight: 800; letter-spacing: .2em; color: var(--accent-2); }
.race-clock strong { display: block; font-family: var(--display); font-size: 31px; font-weight: 700; font-variant-numeric: tabular-nums; line-height: 1.1; letter-spacing: .04em; }
.race-clock small { font-size: 8px; font-weight: 800; letter-spacing: .14em; color: rgba(255,255,255,.55); }
.checkpoint-hint { padding: 7px 12px; background: rgba(8,10,14,.56); border: 1px solid rgba(109,231,255,.22); font-size: 8px; font-weight: 800; letter-spacing: .14em; color: rgba(109,231,255,.8); }
.checkpoint-hint b { color: #fff; }

.hud-top-right { position: absolute; top: calc(24px + var(--safe-top)); right: clamp(20px, 3vw, 46px); display: flex; gap: 6px; }
.icon-button { display: flex; flex-direction: column; align-items: center; gap: 3px; width: 55px; padding: 8px 4px 7px; border: 1px solid rgba(255,255,255,.14); background: rgba(8,10,14,.44); backdrop-filter: blur(10px); cursor: pointer; transition: background .2s, border-color .2s; }
.icon-button:hover { background: rgba(255,255,255,.1); border-color: rgba(255,255,255,.3); }
.icon-button span { font-family: var(--display); font-size: 18px; line-height: 1; color: var(--accent-2); }
.icon-button small { font-size: 6px; font-weight: 800; letter-spacing: .12em; color: rgba(255,255,255,.5); }

.skill-chain { position: absolute; top: 23%; right: clamp(26px, 4vw, 58px); display: flex; flex-direction: column; align-items: flex-end; padding-right: 12px; border-right: 2px solid var(--accent-2); animation: slideIn .25s ease; }
.skill-chain span { font-size: 7px; font-weight: 800; letter-spacing: .22em; color: var(--accent-2); }
.skill-chain strong { font-family: var(--display); font-size: 42px; font-style: italic; font-weight: 800; line-height: .9; color: #fff; text-shadow: 0 0 30px rgba(255,190,61,.3); }
.skill-chain small { font-size: 8px; font-weight: 800; letter-spacing: .16em; color: rgba(255,255,255,.5); }

.hud-bottom-left { position: absolute; left: clamp(20px, 3vw, 46px); bottom: calc(26px + var(--safe-bottom)); display: flex; align-items: flex-end; gap: 18px; }
.speedo { position: relative; width: 158px; height: 158px; }
.speedo-arc { position: absolute; inset: 0; transform: rotate(136deg); }
.speedo-arc svg { width: 100%; height: 100%; overflow: visible; }
.speedo-arc circle { fill: none; stroke-width: 3.5; stroke-linecap: round; stroke-dasharray: 235 315; }
.arc-bg { stroke: rgba(255,255,255,.12); }
.arc-fill { stroke: url(#speedGradient); stroke: var(--accent-2); filter: drop-shadow(0 0 5px rgba(255,150,40,.6)); transition: stroke-dashoffset .08s linear; }
.speed-value { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; padding-top: 16px; }
.speed-value strong { font-family: var(--display); font-size: 64px; font-style: italic; font-weight: 800; line-height: .74; letter-spacing: -.035em; font-variant-numeric: tabular-nums; text-shadow: 0 4px 26px rgba(0,0,0,.36); }
.speed-value span { margin-top: 8px; font-size: 7px; font-weight: 800; letter-spacing: .22em; color: var(--accent-2); }
.gear { position: absolute; left: 50%; bottom: -1px; transform: translateX(-50%); display: flex; align-items: baseline; gap: 4px; }
.gear small { font-size: 6px; font-weight: 800; letter-spacing: .12em; color: rgba(255,255,255,.4); }
