.car-hud { display: flex; align-items: center; gap: 9px; padding-bottom: 9px; }
.mini-class { display: grid; place-items: center; width: 30px; height: 30px; border: 1px solid rgba(255,190,61,.5); font-family: var(--display); font-size: 17px; font-style: italic; font-weight: 800; color: var(--accent-2); }
.car-hud strong { display: block; font-family: var(--display); font-size: 18px; font-weight: 700; letter-spacing: .05em; }
.car-hud small { display: block; margin-top: 1px; font-size: 6px; font-weight: 800; letter-spacing: .14em; color: rgba(255,255,255,.38); }

.hud-bottom-right { position: absolute; right: clamp(20px, 3vw, 46px); bottom: calc(26px + var(--safe-bottom)); width: 174px; height: 174px; }
#minimap { width: 174px; height: 174px; display: block; border-radius: 50%; background: rgba(7,9,13,.6); border: 1px solid rgba(255,255,255,.16); box-shadow: 0 10px 40px rgba(0,0,0,.3); }
.map-ring { position: absolute; inset: 7px; border-radius: 50%; border: 1px dashed rgba(255,255,255,.12); pointer-events: none; }
.map-coords { position: absolute; left: 50%; bottom: -15px; transform: translateX(-50%); white-space: nowrap; font-size: 6px; font-weight: 800; letter-spacing: .14em; color: rgba(255,255,255,.35); }

.toast-wrap { position: absolute; top: 20%; left: 50%; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 6px; }
.toast { padding: 9px 18px; border-left: 2px solid var(--accent-2); background: rgba(7,9,13,.78); backdrop-filter: blur(8px); font-size: 9px; font-weight: 800; letter-spacing: .13em; text-align: center; animation: toastIn .3s ease, toastOut .4s ease 2.6s forwards; }
