.mobile-controls { display: none; }

/* ---------- overlay panels ---------- */
.overlay-panel { position: absolute; inset: 0; z-index: 40; display: grid; place-items: center; padding: 24px; background: rgba(4,6,9,.58); backdrop-filter: blur(9px); }
.panel-card { position: relative; width: min(720px, 94vw); max-height: 88vh; overflow: auto; padding: clamp(24px, 4vw, 44px); border: 1px solid rgba(255,255,255,.15); background: linear-gradient(145deg, rgba(16,18,24,.96), rgba(8,10,14,.97)); box-shadow: 0 40px 120px rgba(0,0,0,.6); scrollbar-width: thin; }
