.close-button { position: absolute; top: 14px; right: 14px; width: 38px; height: 38px; border: 1px solid rgba(255,255,255,.14); background: rgba(255,255,255,.04); color: rgba(255,255,255,.7); font-size: 22px; line-height: 1; cursor: pointer; }
.close-button:hover { background: rgba(255,255,255,.1); }
.panel-actions { margin-top: 26px; }

.event-list { display: grid; gap: 8px; }
.event-item { position: relative; display: grid; grid-template-columns: 56px 1fr auto; align-items: center; gap: 15px; padding: 15px 18px; border: 1px solid rgba(255,255,255,.1); background: rgba(255,255,255,.025); cursor: pointer; text-align: left; transition: background .2s, border-color .2s, transform .2s; }
.event-item:hover { background: rgba(255,255,255,.06); border-color: rgba(255,190,61,.38); transform: translateX(3px); }
.event-icon { display: grid; place-items: center; width: 48px; height: 48px; border: 1px solid rgba(255,190,61,.35); color: var(--accent-2); font-family: var(--display); font-size: 22px; font-weight: 800; }
.event-item strong { display: block; font-family: var(--display); font-size: 23px; font-weight: 700; letter-spacing: .04em; }
.event-item small { display: block; margin-top: 2px; font-size: 8px; font-weight: 700; letter-spacing: .1em; color: var(--muted); }
.event-item em { font-family: var(--display); font-size: 13px; font-style: normal; font-weight: 700; color: var(--accent-2); letter-spacing: .08em; }
.event-item.locked { opacity: .42; cursor: not-allowed; }
.event-item.locked:hover { transform: none; border-color: rgba(255,255,255,.1); background: rgba(255,255,255,.025); }

.map-card { width: min(860px, 94vw); }
.map-heading { display: flex; align-items: flex-end; justify-content: space-between; }
.map-heading h2 { margin-bottom: 12px; }
#world-map { width: 100%; aspect-ratio: 1; display: block; border: 1px solid rgba(255,255,255,.12); background: #0b1012; }
.map-legend { display: flex; flex-wrap: wrap; gap: 20px; margin-top: 15px; font-size: 8px; font-weight: 800; letter-spacing: .12em; color: var(--muted); }
.map-legend span { display: flex; align-items: center; gap: 6px; }
.dot { display: inline-block; width: 7px; height: 7px; border-radius: 50%; }
.dot.you { background: #fff; box-shadow: 0 0 8px #fff; }
