.settings { display: grid; gap: 15px; margin-top: 28px; padding-top: 20px; border-top: 1px solid rgba(255,255,255,.1); }
.settings label { display: grid; grid-template-columns: 118px 1fr 46px; align-items: center; gap: 12px; font-size: 8px; font-weight: 800; letter-spacing: .12em; color: var(--muted); }
.settings input[type=range] { width: 100%; height: 2px; appearance: none; background: rgba(255,255,255,.16); accent-color: var(--accent); }
.settings input[type=range]::-webkit-slider-thumb { appearance: none; width: 11px; height: 11px; border-radius: 50%; background: var(--accent-2); box-shadow: 0 0 8px rgba(255,190,61,.6); }
.settings select { padding: 6px; border: 1px solid rgba(255,255,255,.16); background: #11151b; color: var(--ink); font-size: 9px; font-weight: 700; letter-spacing: .08em; }
.settings b { font-family: var(--display); font-size: 14px; color: var(--ink); text-align: right; font-weight: 700; }
.pause-controls { display: flex; flex-wrap: wrap; align-items: center; gap: 7px; margin-top: 22px; font-size: 8px; font-weight: 700; letter-spacing: .08em; color: var(--dim); }

.results-card { width: min(580px, 94vw); text-align: center; }
.result-time { display: flex; flex-direction: column; align-items: center; margin: 10px 0 24px; }
.result-time strong { font-family: var(--display); font-size: 74px; font-style: italic; font-weight: 800; line-height: .9; color: var(--accent-2); }
.result-time span { margin-top: 7px; font-size: 8px; font-weight: 800; letter-spacing: .2em; color: var(--muted); }
.standings { display: grid; gap: 5px; margin: 0 auto 20px; max-width: 420px; text-align: left; }
.standing { display: grid; grid-template-columns: 26px 1fr auto; align-items: center; gap: 10px; padding: 9px 12px; background: rgba(255,255,255,.035); border-left: 2px solid transparent; font-size: 10px; font-weight: 700; letter-spacing: .06em; }
.standing.you { border-left-color: var(--accent-2); background: rgba(255,190,61,.08); }
.standing b { font-family: var(--display); font-size: 16px; font-style: italic; color: var(--accent-2); }
