.garage-car { position: relative; padding: 14px 10px 12px; border: 1px solid rgba(255,255,255,.1); background: rgba(255,255,255,.025); cursor: pointer; text-align: left; transition: border-color .2s, background .2s, transform .2s; }
.garage-car:hover { background: rgba(255,255,255,.06); transform: translateY(-2px); }
.garage-car.active { border-color: var(--accent-2); background: rgba(255,190,61,.08); }
.garage-car .swatch { height: 4px; margin-bottom: 10px; background: var(--swatch); }
.garage-car strong { display: block; font-family: var(--display); font-size: 17px; font-weight: 700; letter-spacing: .03em; line-height: 1; }
.garage-car small { display: block; margin-top: 4px; font-size: 6px; font-weight: 800; letter-spacing: .1em; color: var(--muted); }
.garage-car em { position: absolute; right: 8px; top: 20px; font-family: var(--display); font-size: 17px; font-style: italic; font-weight: 800; color: var(--accent-2); }
.garage-footer { display: flex; align-items: center; justify-content: space-between; gap: 18px; margin-top: 22px; padding-top: 18px; border-top: 1px solid rgba(255,255,255,.1); }
