/* ---------- speed lines ---------- */
#speed-lines { position: absolute; inset: 0; z-index: 5; pointer-events: none; opacity: 0; transition: opacity .2s; background: repeating-conic-gradient(from 0deg at 50% 50%, transparent 0deg 3deg, rgba(255,255,255,.045) 3.3deg 3.7deg, transparent 4deg 8deg); mask-image: radial-gradient(circle, transparent 0 42%, #000 74%); -webkit-mask-image: radial-gradient(circle, transparent 0 42%, #000 74%); }

@keyframes blink { 0%, 100% { opacity: 1; } 50% { opacity: .25; } }
@keyframes slideIn { from { opacity: 0; transform: translateX(18px); } to { opacity: 1; transform: none; } }
@keyframes toastIn { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-6px); } }

