    tire.rotation.z = Math.PI / 2;
    tire.castShadow = true;
    spin.add(tire);
    const rim = new THREE.Mesh(new THREE.CylinderGeometry(d.wheelR * 0.62, d.wheelR * 0.62, 0.3, 10), mats.rim);
