    spin.add(rim);
    const hub = new THREE.Mesh(new THREE.CylinderGeometry(d.wheelR * 0.2, d.wheelR * 0.2, 0.32, 8), mats.trim);
    hub.rotation.z = Math.PI / 2;
    spin.add(hub);
    for (let s = 0; s < 5; s++) {
