  const rand = mulberry32(22);
  ctx.clearRect(0, 0, 512, 256);
  for (let i = 0; i < 28; i++) {
    const x = 70 + rand() * 372;
    const y = 95 + rand() * 70;
    const r = 35 + rand() * 75;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, 'rgba(255,248,235,.48)');
    g.addColorStop(0.55, 'rgba(255,245,228,.2)');
