import * as THREE from 'three';
import { CITY, EVENTS, FESTIVAL, LAKE, ROADS } from './config.js';
import { Path3D } from './path.js';
import {
  clamp, lerp, smoothstep, fbm, noise2, mulberry32, makeCanvas, TAU,
} from './utils.js';
import {
  makeAsphaltTexture, makeGlowTexture, makeStarfieldTexture,
} from './world/textures.js';
import { buildWorldProps } from './world/props.js';
import { buildWorldMap } from './world/map.js';

export const WORLD_SIZE = 4000;
export const WORLD_HALF = WORLD_SIZE / 2;
export const WATER_LEVEL = 1.5;
const FIELD_SIZE = 1024;

const SKY_VERTEX = `
  varying vec3 vDir;
  void main() {
    vDir = normalize(position);
    vec4 p = modelViewMatrix * vec4(position, 1.0);
    gl_Position = projectionMatrix * p;
  }
`;

const SKY_FRAGMENT = `
  varying vec3 vDir;
  uniform vec3 uTop;
  uniform vec3 uHorizon;
  uniform vec3 uHaze;
  uniform vec3 uSunColor;
  uniform vec3 uSunDir;
  uniform float uNight;
  uniform float uTime;

  float hash(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
  }

  void main() {
    vec3 dir = normalize(vDir);
    float h = clamp(dir.y * 0.5 + 0.5, 0.0, 1.0);
    float band = smoothstep(0.43, 0.66, h);
    vec3 col = mix(uHorizon, uTop, band);
    float low = 1.0 - smoothstep(0.42, 0.56, h);
    col = mix(col, uHaze, low * 0.68);
    float sunDot = max(dot(dir, normalize(uSunDir)), 0.0);
    float disk = pow(sunDot, 1450.0) * 3.2;
    float glow = pow(sunDot, 18.0) * 0.34 + pow(sunDot, 5.0) * 0.1;
    col += uSunColor * (disk + glow);
    // Warm horizon flare opposite the sun, giving the low-poly world some depth.
    float rim = pow(1.0 - abs(dir.y), 9.0) * 0.18;
    col += vec3(1.0, 0.36, 0.16) * rim;
    // Sparse stars, only after dusk.
    vec3 sdir = floor(dir * 430.0);
    float star = step(0.9982, hash(sdir.xy + sdir.z * 19.7));
    star *= smoothstep(0.48, 0.9, h) * uNight;
    col += vec3(0.82, 0.9, 1.0) * star * (0.7 + 0.3 * sin(uTime * 2.0 + hash(sdir.xy) * 8.0));
    gl_FragColor = vec4(col, 1.0);
  }
`;

const WATER_VERTEX = `
  uniform float uTime;
  varying vec3 vWorld;
  varying vec2 vUv;
  void main() {
    vUv = uv;
    vec3 p = position;
    p.y += sin(p.x * 0.09 + uTime * 0.9) * 0.07 + sin(p.z * 0.13 - uTime * 0.7) * 0.05;
    vec4 wp = modelMatrix * vec4(p, 1.0);
    vWorld = wp.xyz;
    gl_Position = projectionMatrix * viewMatrix * wp;
  }
`;

const WATER_FRAGMENT = `
  uniform float uTime;
  uniform vec3 uDeep;
  uniform vec3 uShallow;
  uniform vec3 uSunColor;
  uniform vec3 uSunDir;
  uniform vec3 uCenter;
  varying vec3 vWorld;
  varying vec2 vUv;
  void main() {
    vec3 n = normalize(vec3(
      sin(vWorld.x * 0.11 + uTime * 0.8) * 0.045,
      1.0,
      cos(vWorld.z * 0.14 - uTime * 0.65) * 0.045
    ));
    vec3 viewDir = normalize(cameraPosition - vWorld);
    float fres = pow(1.0 - max(dot(viewDir, n), 0.0), 2.4);
    vec3 col = mix(uDeep, uShallow, 0.35 + fres * 0.55);
    float spec = pow(max(dot(reflect(-normalize(uSunDir), n), viewDir), 0.0), 120.0);
    col += uSunColor * spec * 1.4;
    float d = length(vWorld.xz - uCenter.xz);
    float foam = smoothstep(312.0, 336.0, d) * (0.55 + 0.45 * sin(vWorld.x * 0.2 + uTime * 1.6));
    col = mix(col, vec3(0.8, 0.91, 0.9), foam * 0.25);
    gl_FragColor = vec4(col, 0.93);
  }
`;

export class World {
  constructor(scene, renderer, quality) {
    this.scene = scene;
    this.renderer = renderer;
    this.quality = quality;
    this.timeOfDay = 17.35;
    this.nightFactor = 0;
    this.roadPaths = [];
    this.roadSamples = [];
    this.colliders = [];
    this.colliderGrid = new Map();
    this.smashables = [];
    this.beacons = [];
    this.traffic = [];
    this.animated = [];
    this.lightPools = [];
    this.cityMaterials = [];
    this.signMaterials = [];
    this.clouds = [];
    this.balloons = [];
    this.boats = [];
    this.turbines = [];
    this.flags = [];
    this.time = 0;

    this.buildRoads();
    this.buildRoadField();
    this.buildTerrain();
    this.buildRoadMeshes();
    this.buildWater();
    this.buildSky();
    this.buildLights();
    this.setTime(this.timeOfDay);
    this.buildEnvironment();
    this.buildSunSprite();
    buildWorldProps(this);
    this.mapCanvas = buildWorldMap(this);
    this.updateNightVisuals();
  }

  rawHeight(x, z) {
    let h = 2.5 + (fbm(x * 0.00072 + 9.3, z * 0.00072 - 4.1, 5, 13) - 0.5) * 44;
    h += (fbm(x * 0.0027 - 2.2, z * 0.0027 + 7.8, 4, 42) - 0.5) * 8;
    h += (noise2(x * 0.014, z * 0.014, 7) - 0.5) * 1.2;

    const cityD = Math.hypot(x - CITY.x, z - CITY.z);
    const cityMask = 1 - smoothstep(CITY.radius * 0.68, CITY.radius, cityD);
    h = lerp(h, 10.4, cityMask * 0.95);

    const festivalD = Math.hypot(x - FESTIVAL.x, z - FESTIVAL.z);
    const festivalMask = 1 - smoothstep(FESTIVAL.radius * 0.42, FESTIVAL.radius, festivalD);
    h = lerp(h, 6.3, festivalMask * 0.97);

    const lakeD = Math.hypot(x - LAKE.x, z - LAKE.z) / LAKE.radius;
    if (lakeD < 1.34) {
      const lakeMask = 1 - smoothstep(0.58, 1.28, lakeD);
      const bed = -10 + lakeD * lakeD * 9;
      h = lerp(h, bed, lakeMask);
    }

    const edge = smoothstep(1260, 1940, Math.max(Math.abs(x), Math.abs(z)));
    h += edge * edge * (120 + fbm(x * 0.0018, z * 0.0018, 4, 61) * 165);
    const north = smoothstep(700, 1900, z) * smoothstep(0.2, 1, fbm(x * 0.0012, z * 0.0011, 4, 91));
    h += north * 24;
    return h;
  }

  buildRoads() {
    for (const road of ROADS) {
      const path = new Path3D(road.points, {
        closed: road.closed,
        spacing: road.kind === 'highway' ? 4.2 : 3.2,
        heightAt: (x, z) => this.rawHeight(x, z),
        smooth: road.kind === 'street' ? 3 : 7,
      });
      path.id = road.id;
      path.width = road.width;
      path.kind = road.kind;
      this.roadPaths.push(path);
      for (const sample of path.samples) {
        sample.width = road.width;
        sample.kind = road.kind;
        this.roadSamples.push(sample);
      }
    }
  }

  buildRoadField() {
    const field = {
      size: FIELD_SIZE,
      cell: WORLD_SIZE / FIELD_SIZE,
      dist: new Float32Array(FIELD_SIZE * FIELD_SIZE).fill(999),
      height: new Float32Array(FIELD_SIZE * FIELD_SIZE),
      width: new Float32Array(FIELD_SIZE * FIELD_SIZE),
    };
    const cell = field.cell;
    for (const road of this.roadPaths) {
      const radius = road.width / 2 + 52;
      const radiusCells = Math.ceil(radius / cell);
      for (const sample of road.samples) {
        const cx = Math.floor((sample.x + WORLD_HALF) / cell);
        const cz = Math.floor((sample.z + WORLD_HALF) / cell);
        for (let oz = -radiusCells; oz <= radiusCells; oz++) {
          const iz = cz + oz;
          if (iz < 0 || iz >= FIELD_SIZE) continue;
          const wz = -WORLD_HALF + (iz + 0.5) * cell;
          const dz = wz - sample.z;
          for (let ox = -radiusCells; ox <= radiusCells; ox++) {
            const ix = cx + ox;
            if (ix < 0 || ix >= FIELD_SIZE) continue;
            const wx = -WORLD_HALF + (ix + 0.5) * cell;
            const dx = wx - sample.x;
            const d = Math.hypot(dx, dz);
            if (d > radius) continue;
            const index = iz * FIELD_SIZE + ix;
            if (d < field.dist[index]) {
              field.dist[index] = d;
              field.height[index] = sample.y;
              field.width[index] = road.width;
            }
          }
        }
      }
    }
    this.roadField = field;
  }

  sampleRoadField(x, z) {
    const f = this.roadField;
    if (!f) return { dist: 999, height: 0, width: 0 };
    const ix = clamp(Math.floor((x + WORLD_HALF) / f.cell), 0, FIELD_SIZE - 1);
    const iz = clamp(Math.floor((z + WORLD_HALF) / f.cell), 0, FIELD_SIZE - 1);
    const index = iz * FIELD_SIZE + ix;
    return { dist: f.dist[index], height: f.height[index], width: f.width[index] };
  }

  heightAt(x, z) {
    const base = this.rawHeight(x, z);
    const road = this.sampleRoadField(x, z);
    if (road.dist < 54) {
      const blend = 1 - smoothstep(11, 54, road.dist);
      const roadY = Math.max(road.height, WATER_LEVEL + 1.2);
      return lerp(base, roadY, blend);
    }
    return base;
  }

  slopeAt(x, z) {
    const e = 2.5;
    const hx = (this.heightAt(x + e, z) - this.heightAt(x - e, z)) / (2 * e);
    const hz = (this.heightAt(x, z + e) - this.heightAt(x, z - e)) / (2 * e);
    return Math.hypot(hx, hz);
  }

  surfaceAt(x, z) {
    const road = this.sampleRoadField(x, z);
    if (road.dist < road.width / 2 + 1.2) return { type: 'asphalt', onRoad: true, grip: 1 };
    if (road.dist < road.width / 2 + 7) return { type: 'shoulder', onRoad: true, grip: 0.87 };
    const h = this.heightAt(x, z);
    if (h < WATER_LEVEL + 1.4) return { type: 'sand', onRoad: false, grip: 0.55 };
    const slope = this.slopeAt(x, z);
    if (slope > 0.62) return { type: 'rock', onRoad: false, grip: 0.52 };
    if (x > CITY.x - CITY.radius && x < CITY.x + CITY.radius && z > CITY.z - CITY.radius && z < CITY.z + CITY.radius) {
      return { type: 'city', onRoad: false, grip: 0.93 };
    }
    return { type: 'grass', onRoad: false, grip: 0.7 };
  }

  buildTerrain() {
    const segments = this.quality.terrainSegments || 300;
    const geometry = new THREE.PlaneGeometry(WORLD_SIZE, WORLD_SIZE, segments, segments);
    geometry.rotateX(-Math.PI / 2);
    const position = geometry.attributes.position;
    for (let i = 0; i < position.count; i++) {
      const x = position.getX(i);
      const z = position.getZ(i);
      position.setY(i, this.heightAt(x, z));
    }
    geometry.computeVertexNormals();
    const normals = geometry.attributes.normal;
    const colors = new Float32Array(position.count * 3);
    const color = new THREE.Color();
    const grassA = new THREE.Color(0x5d7645);
    const grassB = new THREE.Color(0x7d8b4d);
    const grassC = new THREE.Color(0x4b673f);
    const dry = new THREE.Color(0x9c8b5e);
    const rock = new THREE.Color(0x706b62);
    const rockDark = new THREE.Color(0x4d4a47);
    const sand = new THREE.Color(0xbda77e);
    const cityGround = new THREE.Color(0x54584e);
    const snow = new THREE.Color(0xd8d9d2);
    for (let i = 0; i < position.count; i++) {
      const x = position.getX(i);
      const z = position.getZ(i);
      const y = position.getY(i);
      const n = noise2(x * 0.026 + 3, z * 0.026 - 1, 11);
      const n2 = noise2(x * 0.006, z * 0.006, 23);
      const slope = 1 - normals.getY(i);
      const road = this.sampleRoadField(x, z);
      if (road.dist < road.width / 2 + 8) {
        color.copy(rockDark).offsetHSL(0, 0, (n - 0.5) * 0.04);
      } else if (y < WATER_LEVEL + 2.2) {
        color.copy(sand).offsetHSL(0, (n - 0.5) * 0.06, (n2 - 0.5) * 0.08);
      } else if (slope > 0.34) {
        color.copy(rock).lerp(rockDark, clamp((slope - 0.34) * 1.4, 0, 1)).offsetHSL(0, 0, (n - 0.5) * 0.05);
      } else if (y > 92) {
        color.copy(snow).offsetHSL(0, 0, (n - 0.5) * 0.05);
      } else if (y > 48) {
        color.copy(rock).lerp(dry, 0.22 + n * 0.22).offsetHSL(0, 0, (n2 - 0.5) * 0.05);
      } else {
        color.copy(grassA).lerp(grassB, n2 * 0.9);
        if (n > 0.62) color.lerp(grassC, 0.45);
        if (y > 24) color.lerp(dry, smoothstep(24, 50, y) * 0.55);
        const cityD = Math.hypot(x - CITY.x, z - CITY.z);
        if (cityD < CITY.radius) color.lerp(cityGround, (1 - smoothstep(CITY.radius * 0.55, CITY.radius, cityD)) * 0.45);
      }
      const festivalD = Math.hypot(x - FESTIVAL.x, z - FESTIVAL.z);
      if (festivalD < FESTIVAL.radius && road.dist > road.width / 2 + 8) {
        color.lerp(new THREE.Color(0x687b48), (1 - smoothstep(80, FESTIVAL.radius, festivalD)) * 0.22);
      }
      colors[i * 3] = color.r;
      colors[i * 3 + 1] = color.g;
      colors[i * 3 + 2] = color.b;
    }
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    const material = new THREE.MeshStandardMaterial({
      vertexColors: true,
      roughness: 0.97,
      metalness: 0,
      flatShading: true,
    });
    this.terrain = new THREE.Mesh(geometry, material);
    this.terrain.receiveShadow = true;
    this.scene.add(this.terrain);
  }

  buildRoadMeshes() {
    const texture = makeAsphaltTexture();
    const material = new THREE.MeshStandardMaterial({
      map: texture,
      color: 0xffffff,
      roughness: 0.88,
      metalness: 0.04,
      polygonOffset: true,
      polygonOffsetFactor: -2,
      polygonOffsetUnits: -2,
    });
    const shoulderMaterial = new THREE.MeshStandardMaterial({
      color: 0x635d4b,
      roughness: 1,
      transparent: true,
      opacity: 0.72,
      polygonOffset: true,
      polygonOffsetFactor: -1,
      polygonOffsetUnits: -1,
    });
    for (const path of this.roadPaths) {
      this.scene.add(this.makeRibbon(path, path.width, path.width / 2 + 0.05, material, true));
      this.scene.add(this.makeRibbon(path, path.width + 6, path.width / 2 + 0.015, shoulderMaterial, false));
    }
  }

  makeRibbon(path, width, lift, material, withUv) {
    const samples = path.samples;
    const count = samples.length;
    const vertices = [];
    const uvs = [];
    const indices = [];
    const half = width / 2;
    let v = 0;
    for (let i = 0; i < count; i++) {
      const s = samples[i];
      if (i > 0) {
        const prev = samples[i - 1];
        v += Math.hypot(s.x - prev.x, s.z - prev.z) / 18;
      }
      vertices.push(s.x + s.rx * half, s.y + lift, s.z + s.rz * half);
      vertices.push(s.x - s.rx * half, s.y + lift, s.z - s.rz * half);
      if (withUv) {
        uvs.push(1, v, 0, v);
      } else {
        uvs.push(1, v, 0, v);
      }
      if (i < count - 1) {
        const a = i * 2;
        indices.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
      }
    }
    if (path.closed) {
      const a = (count - 1) * 2;
      indices.push(a, 0, a + 1, a + 1, 0, 1);
    }
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
    geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
    geometry.setIndex(indices);
    geometry.computeVertexNormals();
    const mesh = new THREE.Mesh(geometry, material);
    mesh.receiveShadow = true;
    mesh.renderOrder = withUv ? 2 : 1;
    return mesh;
  }

  buildWater() {
    const geometry = new THREE.CircleGeometry(LAKE.radius + 4, 80);
    geometry.rotateX(-Math.PI / 2);
    this.waterMaterial = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0 },
        uDeep: { value: new THREE.Color(0x123d4b) },
        uShallow: { value: new THREE.Color(0x3f8890) },
        uSunColor: { value: new THREE.Color(0xffd7a0) },
        uSunDir: { value: new THREE.Vector3(0.4, 0.3, 0.2).normalize() },
        uCenter: { value: new THREE.Vector3(LAKE.x, 0, LAKE.z) },
      },
      vertexShader: WATER_VERTEX,
      fragmentShader: WATER_FRAGMENT,
      transparent: true,
      depthWrite: false,
    });
    this.water = new THREE.Mesh(geometry, this.waterMaterial);
    this.water.position.set(LAKE.x, WATER_LEVEL, LAKE.z);
    this.water.renderOrder = 3;
    this.scene.add(this.water);
  }

  buildSky() {
    const geometry = new THREE.SphereGeometry(6800, 32, 20);
    this.skyMaterial = new THREE.ShaderMaterial({
      uniforms: {
        uTop: { value: new THREE.Color(0x2f67b6) },
        uHorizon: { value: new THREE.Color(0xf0b27c) },
        uHaze: { value: new THREE.Color(0xffc08a) },
        uSunColor: { value: new THREE.Color(0xffd6a0) },
        uSunDir: { value: new THREE.Vector3(0.4, 0.2, 0.3).normalize() },
        uNight: { value: 0 },
        uTime: { value: 0 },
      },
      vertexShader: SKY_VERTEX,
      fragmentShader: SKY_FRAGMENT,
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
    });
    this.sky = new THREE.Mesh(geometry, this.skyMaterial);
    this.sky.frustumCulled = false;
    this.sky.renderOrder = -10;
    this.scene.add(this.sky);
    this.scene.fog = new THREE.FogExp2(0xd3a078, 0.00042);
  }

  buildLights() {
    this.hemi = new THREE.HemisphereLight(0xbfd4ff, 0x38402b, 0.75);
    this.scene.add(this.hemi);
    this.sun = new THREE.DirectionalLight(0xffc27a, 3.0);
    this.sun.castShadow = this.quality.shadows;
    this.sun.shadow.mapSize.set(this.quality.shadowSize, this.quality.shadowSize);
    this.sun.shadow.camera.left = -230;
    this.sun.shadow.camera.right = 230;
    this.sun.shadow.camera.top = 230;
    this.sun.shadow.camera.bottom = -230;
    this.sun.shadow.camera.near = 10;
    this.sun.shadow.camera.far = 1000;
    this.sun.shadow.bias = -0.0006;
    this.sun.shadow.normalBias = 0.03;
    this.sun.target.position.set(0, 0, 0);
    this.scene.add(this.sun);
    this.scene.add(this.sun.target);
    this.moon = new THREE.DirectionalLight(0x8aa8ff, 0.18);
    this.moon.position.set(-220, 360, 120);
    this.scene.add(this.moon);
  }

  setTime(time) {
    this.timeOfDay = time;
    const t = ((time % 24) + 24) % 24;
    const theta = (t / 24) * TAU - Math.PI / 2;
    const elevation = Math.sin(((t - 6) / 12) * Math.PI) * 0.98;
    const cosEl = Math.cos(elevation);
    this.sunDir = new THREE.Vector3(Math.cos(theta) * cosEl, Math.sin(elevation), Math.sin(theta) * cosEl).normalize();
    const day = smoothstep(-0.06, 0.22, this.sunDir.y);
    const sunset = (1 - smoothstep(0.03, 0.4, Math.abs(this.sunDir.y))) * smoothstep(-0.08, 0.06, this.sunDir.y);
    const night = 1 - smoothstep(-0.07, 0.2, this.sunDir.y);
    this.nightFactor = night;
    this.dayFactor = day;

    const topNight = new THREE.Color(0x020716);
    const topDay = new THREE.Color(0x2c66b6);
    const topDusk = new THREE.Color(0x273c76);
    const horNight = new THREE.Color(0x0b1730);
    const horDay = new THREE.Color(0xb9d5e2);
    const horDusk = new THREE.Color(0xff9357);
    const hazeNight = new THREE.Color(0x0d1930);
    const hazeDay = new THREE.Color(0xc5dce0);
    const hazeDusk = new THREE.Color(0xffad78);
    const top = topNight.clone().lerp(topDay, day).lerp(topDusk, sunset * 0.5);
    const horizon = horNight.clone().lerp(horDay, day).lerp(horDusk, sunset * 0.92);
    const haze = hazeNight.clone().lerp(hazeDay, day).lerp(hazeDusk, sunset * 0.95);
    const sunColor = new THREE.Color(0xfff0cf).lerp(new THREE.Color(0xff6b2f), sunset).lerp(new THREE.Color(0x6f8dff), night * 0.75);

    this.skyMaterial.uniforms.uTop.value.copy(top);
    this.skyMaterial.uniforms.uHorizon.value.copy(horizon);
    this.skyMaterial.uniforms.uHaze.value.copy(haze);
    this.skyMaterial.uniforms.uSunColor.value.copy(sunColor);
    this.skyMaterial.uniforms.uSunDir.value.copy(this.sunDir);
    this.skyMaterial.uniforms.uNight.value = night;

    this.scene.fog.color.copy(horizon).lerp(haze, 0.4).multiplyScalar(0.78 + day * 0.18);
    this.scene.fog.density = 0.00042 + night * 0.00018;

    this.sun.color.copy(new THREE.Color(0xfff2dc).lerp(new THREE.Color(0xff9b55), sunset * 0.9));
    this.sun.intensity = 0.15 + day * 3.25 + sunset * 0.6;
    this.sun.visible = this.sunDir.y > -0.08;
    this.hemi.intensity = 0.2 + day * 0.65;
    this.hemi.color.copy(new THREE.Color(0x8fa8d8).lerp(new THREE.Color(0xdbe8ff), day));
    this.hemi.groundColor.copy(new THREE.Color(0x1a211d).lerp(new THREE.Color(0x45513a), day));
    this.moon.intensity = night * 0.42;

    if (this.waterMaterial) {
      this.waterMaterial.uniforms.uSunDir.value.copy(this.sunDir);
      this.waterMaterial.uniforms.uSunColor.value.copy(sunColor);
      this.waterMaterial.uniforms.uDeep.value.copy(new THREE.Color(0x0b2733).lerp(new THREE.Color(0x123d4b), day));
      this.waterMaterial.uniforms.uShallow.value.copy(new THREE.Color(0x204e5d).lerp(new THREE.Color(0x4f9aa0), day));
    }
    if (this.sunSprite) {
      this.sunSprite.position.copy(this.sunDir).multiplyScalar(4200);
      this.sunSprite.material.opacity = clamp((this.sunDir.y + 0.06) * 2.2, 0, 0.9);
    }
    this.updateNightVisuals();
  }

  updateNightVisuals() {
    const night = this.nightFactor;
    const lightsOn = night > 0.34;
    for (const mat of this.cityMaterials) mat.emissiveIntensity = lightsOn ? 1.45 : 0.12;
    for (const mat of this.signMaterials) mat.emissiveIntensity = lightsOn ? 2.1 : 0.25;
    for (const pool of this.lightPools) pool.visible = lightsOn;
    for (const item of this.animated) {
      if (item.userData?.nightOnly) item.visible = lightsOn;
    }
  }

  buildEnvironment() {
    const canvas = makeCanvas(1024, 512);
    const ctx = canvas.getContext('2d');
    const top = this.skyMaterial.uniforms.uTop.value;
    const horizon = this.skyMaterial.uniforms.uHorizon.value;
    const haze = this.skyMaterial.uniforms.uHaze.value;
    const g = ctx.createLinearGradient(0, 0, 0, 512);
    g.addColorStop(0, `#${top.getHexString()}`);
    g.addColorStop(0.5, `#${horizon.getHexString()}`);
    g.addColorStop(0.6, `#${haze.getHexString()}`);
    g.addColorStop(0.68, '#4f4a40');
    g.addColorStop(1, '#171b18');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, 1024, 512);
    const sunX = 512 + this.sunDir.x * 300;
    const sunY = 256 - this.sunDir.y * 180;
    const sg = ctx.createRadialGradient(sunX, sunY, 0, sunX, sunY, 100);
    sg.addColorStop(0, 'rgba(255,245,220,1)');
    sg.addColorStop(0.2, 'rgba(255,190,110,.75)');
    sg.addColorStop(1, 'rgba(255,140,60,0)');
    ctx.fillStyle = sg;
    ctx.fillRect(0, 0, 1024, 512);
    const texture = new THREE.CanvasTexture(canvas);
    texture.mapping = THREE.EquirectangularReflectionMapping;
    texture.colorSpace = THREE.SRGBColorSpace;
    const pmrem = new THREE.PMREMGenerator(this.renderer);
    this.environment = pmrem.fromEquirectangular(texture).texture;
    this.scene.environment = this.environment;
    this.scene.environmentIntensity = 0.62;
    texture.dispose();
    pmrem.dispose();
  }

  buildSunSprite() {
    const texture = makeGlowTexture('rgba(255,250,232,1)', 'rgba(255,130,40,0)');
    const material = new THREE.SpriteMaterial({
      map: texture,
      transparent: true,
      opacity: 0.8,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      fog: false,
    });
    this.sunSprite = new THREE.Sprite(material);
    this.sunSprite.scale.set(950, 950, 1);
    this.sunSprite.position.copy(this.sunDir).multiplyScalar(4200);
    this.scene.add(this.sunSprite);
  }

  addCollider(collider) {
    collider._gridX = Math.floor(collider.x / 64);
    collider._gridZ = Math.floor(collider.z / 64);
    this.colliders.push(collider);
    const key = `${collider._gridX}|${collider._gridZ}`;
    if (!this.colliderGrid.has(key)) this.colliderGrid.set(key, []);
    this.colliderGrid.get(key).push(collider);
  }

  addCircleCollider(x, z, radius, type = 'prop') {
    this.addCollider({ shape: 'circle', x, z, radius, type });
  }

  addBoxCollider(x, z, halfW, halfD, type = 'building') {
    this.addCollider({ shape: 'box', x, z, halfW, halfD, type });
  }

  resolveVehicle(position, velocity, radius) {
    let hit = false;
    const cx = Math.floor(position.x / 64);
    const cz = Math.floor(position.z / 64);
    for (let oz = -1; oz <= 1; oz++) {
      for (let ox = -1; ox <= 1; ox++) {
        const list = this.colliderGrid.get(`${cx + ox}|${cz + oz}`);
        if (!list) continue;
        for (const c of list) {
          if (c.shape === 'circle') {
            const dx = position.x - c.x;
            const dz = position.z - c.z;
            const d = Math.hypot(dx, dz);
            const min = radius + c.radius;
            if (d < min && d > 0.0001) {
              const nx = dx / d;
              const nz = dz / d;
              position.x += nx * (min - d);
              position.z += nz * (min - d);
              const vn = velocity.x * nx + velocity.z * nz;
              if (vn < 0) {
                velocity.x -= nx * vn * 1.3;
                velocity.z -= nz * vn * 1.3;
              }
              hit = true;
            }
          } else {
            const minX = c.x - c.halfW - radius;
            const maxX = c.x + c.halfW + radius;
            const minZ = c.z - c.halfD - radius;
            const maxZ = c.z + c.halfD + radius;
            if (position.x > minX && position.x < maxX && position.z > minZ && position.z < maxZ) {
              const left = position.x - minX;
              const right = maxX - position.x;
              const back = position.z - minZ;
              const front = maxZ - position.z;
              const min = Math.min(left, right, back, front);
              let nx = 0;
              let nz = 0;
              if (min === left) nx = -1;
              else if (min === right) nx = 1;
              else if (min === back) nz = -1;
              else nz = 1;
              position.x += nx * min;
              position.z += nz * min;
              const vn = velocity.x * nx + velocity.z * nz;
              if (vn < 0) {
                velocity.x -= nx * vn * 1.25;
                velocity.z -= nz * vn * 1.25;
              }
              hit = true;
            }
          }
        }
      }
    }
    const bound = WORLD_HALF - 30;
    if (position.x < -bound) { position.x = -bound; velocity.x = Math.abs(velocity.x) * 0.3; hit = true; }
    if (position.x > bound) { position.x = bound; velocity.x = -Math.abs(velocity.x) * 0.3; hit = true; }
    if (position.z < -bound) { position.z = -bound; velocity.z = Math.abs(velocity.z) * 0.3; hit = true; }
    if (position.z > bound) { position.z = bound; velocity.z = -Math.abs(velocity.z) * 0.3; hit = true; }
    return hit;
  }

  checkBoards(position) {
    const smashed = [];
    for (const board of this.smashables) {
      if (!board.active) continue;
      const dx = position.x - board.position.x;
      const dz = position.z - board.position.z;
      const dy = position.y + 1.2 - board.position.y;
      if (dx * dx + dz * dz < 16 && Math.abs(dy) < 5.5) {
        board.active = false;
        board.group.visible = false;
        smashed.push(board);
      }
    }
    return smashed;
  }

  update(dt, playerPos, elapsed) {
    this.time = elapsed;
    this.waterMaterial.uniforms.uTime.value = elapsed;
    this.skyMaterial.uniforms.uTime.value = elapsed;

    if (this.sun) {
      const target = playerPos || new THREE.Vector3();
      this.sun.position.copy(target).addScaledVector(this.sunDir, 420);
      this.sun.target.position.copy(target);
      this.sun.target.updateMatrixWorld();
      this.moon.position.copy(target).add(new THREE.Vector3(-180, 320, 100));
    }
    this.sky.position.copy(playerPos || new THREE.Vector3());

    for (const cloud of this.clouds) {
      cloud.position.x += cloud.userData.speed * dt;
      if (cloud.position.x > 2400) cloud.position.x = -2400;
    }
    for (const item of this.animated) {
      if (item.userData?.spin) item.rotation[item.userData.spinAxis || 'y'] += item.userData.spin * dt;
      if (item.userData?.bob) {
        item.position.y = item.userData.baseY + Math.sin(elapsed * item.userData.bobSpeed + item.userData.phase) * item.userData.bob;
      }
      if (item.userData?.orbit) {
        const a = elapsed * item.userData.orbit.speed + item.userData.orbit.phase;
        item.position.x = item.userData.orbit.cx + Math.cos(a) * item.userData.orbit.radius;
        item.position.z = item.userData.orbit.cz + Math.sin(a) * item.userData.orbit.radius;
      }
      if (item.userData?.pulse) {
        const s = 1 + Math.sin(elapsed * 2.4 + item.userData.pulse.phase) * 0.06;
        item.scale.setScalar(item.userData.pulse.base * s);
      }
    }
    for (const board of this.smashables) {
      if (!board.active) continue;
      board.group.rotation.y += dt * 0.8;
      board.group.position.y = board.baseY + Math.sin(elapsed * 1.7 + board.phase) * 0.25;
      if (board.glow) board.glow.material.opacity = 0.45 + Math.sin(elapsed * 2.2 + board.phase) * 0.12;
    }
    for (const beacon of this.beacons) {
      beacon.group.rotation.y += dt * 0.6;
      const s = 1 + Math.sin(elapsed * 2 + beacon.phase) * 0.08;
      beacon.ring.scale.setScalar(s);
    }
    for (const turbine of this.turbines) turbine.blades.rotation.z += turbine.speed * dt;
    for (const traffic of this.traffic) traffic.update(dt);
  }
}

import * as THREE from 'three';
import { CITY } from '../config.js';
import { mulberry32 } from '../utils.js';
import { makeSignTexture, makeWindowTextures } from './textures.js';

export function buildCity(world) {
  const { scene } = world;
  const group = new THREE.Group();
  group.name = 'apex-city';
  scene.add(group);
  const rand = mulberry32(881);

  const variants = [
    makeWindowTextures(12, 0xffc477),
    makeWindowTextures(42, 0x9edcff),
    makeWindowTextures(77, 0xff8f67),
    makeWindowTextures(109, 0xffe3a1),
  ];
  const materials = variants.map(({ map, glow }) => {
    const mat = new THREE.MeshStandardMaterial({
      map,
      emissiveMap: glow,
      emissive: 0xffffff,
      emissiveIntensity: 0.12,
      roughness: 0.72,
      metalness: 0.22,
    });
    world.cityMaterials.push(mat);
    return mat;
  });
  const roofMat = new THREE.MeshStandardMaterial({ color: 0x22262b, roughness: 0.84, metalness: 0.3 });
  const darkMetal = new THREE.MeshStandardMaterial({ color: 0x14171b, roughness: 0.6, metalness: 0.55 });
  const neonColors = ['#6de7ff', '#ff5a2a', '#ffbe3d', '#c8ff45', '#ff6cc7'];
  const signTexts = ['HORIZON', 'APEX', 'NITRO', 'NIGHT', 'VOLT', 'GARAGE', 'MOTOR', 'SUSHI'];

  const columns = [824, 958, 1092, 1226];
  const rows = [-552, -700, -848, -996];
  for (let iz = 0; iz < rows.length; iz++) {
    for (let ix = 0; ix < columns.length; ix++) {
      const bx = columns[ix] + (rand() - 0.5) * 12;
      const bz = rows[iz] + (rand() - 0.5) * 12;
      const road = world.sampleRoadField(bx, bz);
      if (road.dist < 24) continue;
      const tower = rand() > 0.78;
      const height = tower ? 72 + rand() * 58 : 14 + rand() * 32;
      const width = tower ? 25 + rand() * 15 : 35 + rand() * 22;
      const depth = tower ? 25 + rand() * 15 : 35 + rand() * 22;
      const ground = world.heightAt(bx, bz);
      const mat = materials[Math.floor(rand() * materials.length)];
      const building = new THREE.Mesh(new THREE.BoxGeometry(width, height, depth), mat);
      building.position.set(bx, ground + height / 2, bz);
      building.castShadow = true;
      building.receiveShadow = true;
      group.add(building);

      const cap = new THREE.Mesh(new THREE.BoxGeometry(width + 1.2, 1.2, depth + 1.2), roofMat);
      cap.position.set(bx, ground + height + 0.6, bz);
      cap.castShadow = true;
      group.add(cap);

      if (height > 30) {
        const box = new THREE.Mesh(new THREE.BoxGeometry(width * 0.35, 3.2, depth * 0.35), darkMetal);
        box.position.set(bx + (rand() - 0.5) * width * 0.25, ground + height + 2.3, bz + (rand() - 0.5) * depth * 0.25);
        group.add(box);
      }
      if (height > 70) {
        const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.35, 14, 5), darkMetal);
        mast.position.set(bx, ground + height + 9, bz);
        group.add(mast);
        const beacon = new THREE.Mesh(
          new THREE.SphereGeometry(0.5, 6, 4),
          new THREE.MeshStandardMaterial({ color: 0xff3311, emissive: 0xff2200, emissiveIntensity: 4 }),
        );
        beacon.position.set(bx, ground + height + 16.2, bz);
        beacon.userData.nightOnly = false;
        group.add(beacon);
      }

      if (rand() > 0.52) {
        const signText = signTexts[Math.floor(rand() * signTexts.length)];
        const signColor = neonColors[Math.floor(rand() * neonColors.length)];
        const tex = makeSignTexture(signText, signColor, 'APEX CITY');
        const signMat = new THREE.MeshStandardMaterial({
          map: tex,
          emissiveMap: tex,
          emissive: 0xffffff,
          emissiveIntensity: 0.3,
          transparent: true,
          roughness: 0.4,
          side: THREE.DoubleSide,
        });
        world.signMaterials.push(signMat);
        const sign = new THREE.Mesh(new THREE.PlaneGeometry(tower ? 9 : 7, tower ? 3.6 : 2.8), signMat);
        const side = rand() > 0.5 ? 1 : -1;
        sign.position.set(bx + side * (width / 2 + 0.08), ground + Math.min(height * 0.62, 27), bz);
        sign.rotation.y = side > 0 ? Math.PI / 2 : -Math.PI / 2;
        group.add(sign);
      }

      if (rand() > 0.68 && height < 45) {
        const awning = new THREE.Mesh(
          new THREE.BoxGeometry(width * 0.72, 0.22, 2.2),
          new THREE.MeshStandardMaterial({ color: rand() > 0.5 ? 0xff5a2a : 0x6de7ff, roughness: 0.65 }),
        );
        awning.position.set(bx, ground + 4, bz + depth / 2 + 1.2);
        awning.rotation.x = 0.08;
        group.add(awning);
      }

      world.addBoxCollider(bx, bz, width / 2, depth / 2, 'building');
    }
  }

  // City entrance sign, aimed at the approach road.
  const entranceX = 930;
  const entranceZ = -382;
  const ground = world.heightAt(entranceX, entranceZ);
  const tex = makeSignTexture('APEX CITY', '#ffbe3d', 'DISTRICT 01 · NIGHT LIFE');
  const signMat = new THREE.MeshStandardMaterial({
    map: tex,
    emissiveMap: tex,
    emissive: 0xffffff,
    emissiveIntensity: 0.55,
    transparent: true,
    roughness: 0.4,
    side: THREE.DoubleSide,
  });
  world.signMaterials.push(signMat);
  const entrance = new THREE.Group();
  entrance.position.set(entranceX, ground, entranceZ);
  entrance.rotation.y = Math.PI * 0.72;
  const sign = new THREE.Mesh(new THREE.PlaneGeometry(20, 7.5), signMat);
  sign.position.y = 11;
  entrance.add(sign);
  for (const side of [-1, 1]) {
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.5, 14, 6), darkMetal);
    pole.position.set(side * 9.5, 7, 0);
    pole.castShadow = true;
    entrance.add(pole);
  }
  group.add(entrance);

  // A low neon strip under the overpass-like edge of the city.
  const stripMat = new THREE.MeshStandardMaterial({ color: 0x6de7ff, emissive: 0x6de7ff, emissiveIntensity: 1.5, roughness: 0.3 });
  world.signMaterials.push(stripMat);
  const strip = new THREE.Mesh(new THREE.BoxGeometry(3, 0.12, 160), stripMat);
  strip.position.set(744, world.heightAt(744, -790) + 7, -790);
  group.add(strip);
}

import * as THREE from 'three';
import { FESTIVAL } from '../config.js';
import { makeBannerTexture, makeCheckeredTexture, makeGlowTexture, makeHorizonScreenTexture } from './textures.js';

function mesh(parent, geo, mat, x = 0, y = 0, z = 0, rx = 0, ry = 0, rz = 0) {
  const m = new THREE.Mesh(geo, mat);
  m.position.set(x, y, z);
  m.rotation.set(rx, ry, rz);
  m.castShadow = true;
  m.receiveShadow = true;
  parent.add(m);
  return m;
}

export function buildFestival(world) {
  const { scene } = world;
  const group = new THREE.Group();
  group.name = 'festival';
  scene.add(group);

  const ground = world.heightAt(FESTIVAL.x, FESTIVAL.z);
  const dark = new THREE.MeshStandardMaterial({ color: 0x111318, roughness: 0.72, metalness: 0.35 });
  const black = new THREE.MeshStandardMaterial({ color: 0x07080a, roughness: 0.88 });
  const concrete = new THREE.MeshStandardMaterial({ color: 0x53534f, roughness: 0.92 });
  const orange = new THREE.MeshStandardMaterial({ color: 0xff5a2a, emissive: 0xff3b13, emissiveIntensity: 0.35, roughness: 0.5 });
  const amber = new THREE.MeshStandardMaterial({ color: 0xffbe3d, emissive: 0xff8a1a, emissiveIntensity: 0.4, roughness: 0.5 });
  const cyan = new THREE.MeshStandardMaterial({ color: 0x6de7ff, emissive: 0x28c8e8, emissiveIntensity: 0.55, roughness: 0.35 });
  const fabricRed = new THREE.MeshStandardMaterial({ color: 0x9c251c, roughness: 0.88, side: THREE.DoubleSide });
  const fabricCream = new THREE.MeshStandardMaterial({ color: 0xd7c5a1, roughness: 0.9, side: THREE.DoubleSide });

  // Rotating display plinth.
  const plinthTop = ground + 0.72;
  mesh(group, new THREE.CylinderGeometry(17, 18.2, 0.72, 48), dark, 0, ground + 0.36, 10);
  mesh(group, new THREE.TorusGeometry(16.4, 0.14, 4, 64), amber, 0, ground + 0.74, 10, Math.PI / 2);
  const ringMat = new THREE.MeshBasicMaterial({ color: 0xffbe3d, transparent: true, opacity: 0.55, blending: THREE.AdditiveBlending, depthWrite: false });
  const ring = new THREE.Mesh(new THREE.RingGeometry(10.8, 11.1, 64), ringMat);
  ring.rotation.x = -Math.PI / 2;
  ring.position.set(0, plinthTop + 0.02, 10);
  group.add(ring);
  world.menuSpawn = { x: 0, y: plinthTop + 0.02, z: 10, yaw: 0.42 };

  // Main stage.
  const stageZ = -58;
  mesh(group, new THREE.BoxGeometry(46, 1.4, 20), black, 0, ground + 0.7, stageZ);
  mesh(group, new THREE.BoxGeometry(42, 0.16, 16), concrete, 0, ground + 1.46, stageZ + 1);
  for (const side of [-1, 1]) {
    mesh(group, new THREE.BoxGeometry(1.4, 15, 1.4), dark, side * 21, ground + 8.2, stageZ - 9);
    mesh(group, new THREE.BoxGeometry(1.4, 15, 1.4), dark, side * 21, ground + 8.2, stageZ + 9);
  }
  mesh(group, new THREE.BoxGeometry(46, 1.2, 22), dark, 0, ground + 16, stageZ);
  mesh(group, new THREE.BoxGeometry(42, 0.25, 18), black, 0, ground + 15.3, stageZ);
  const screenTexture = makeHorizonScreenTexture();
  const screenMat = new THREE.MeshBasicMaterial({ map: screenTexture, toneMapped: false });
  const screen = mesh(group, new THREE.PlaneGeometry(30, 10.5), screenMat, 0, ground + 9.2, stageZ + 9.15);
  screen.castShadow = false;
  mesh(group, new THREE.BoxGeometry(31, 11.5, 0.6), black, 0, ground + 9.2, stageZ + 8.8);
  for (const side of [-1, 1]) {
    for (let i = 0; i < 3; i++) {
      mesh(group, new THREE.BoxGeometry(2.4, 3.1, 2.1), black, side * (16.8 + i * 1.5), ground + 3.2, stageZ + 6.8 - i * 2.2);
      mesh(group, new THREE.CylinderGeometry(0.55, 0.55, 0.15, 10), dark, side * (16.8 + i * 1.5), ground + 4.1, stageZ + 7.9 - i * 2.2, Math.PI / 2);
    }
  }
  // Stage light bars.
  for (let i = 0; i < 6; i++) {
    const x = -16 + i * 6.4;
    mesh(group, new THREE.BoxGeometry(3.2, 0.45, 0.8), dark, x, ground + 14.4, stageZ + 8.5);
    for (let j = -1; j <= 1; j++) {
      mesh(group, new THREE.CylinderGeometry(0.3, 0.3, 0.3, 8), j === 0 ? amber : orange, x + j * 1.05, ground + 14.1, stageZ + 8.5, Math.PI / 2);
    }
  }
  const stageLightA = new THREE.PointLight(0xff7a30, 30, 95, 1.7);
  stageLightA.position.set(-12, ground + 9, stageZ + 14);
  group.add(stageLightA);
  const stageLightB = new THREE.PointLight(0x6de7ff, 24, 90, 1.7);
  stageLightB.position.set(13, ground + 8, stageZ + 15);
  group.add(stageLightB);
  const stageLightC = new THREE.PointLight(0xffbe3d, 18, 70, 1.7);
  stageLightC.position.set(0, ground + 3, stageZ + 13);
  group.add(stageLightC);

  // Festival towers.
  for (const [x, z] of [[-42, 24], [42, 24], [-48, -18], [48, -18]]) {
    const tower = new THREE.Group();
    tower.position.set(x, ground, z);
    mesh(tower, new THREE.CylinderGeometry(0.35, 0.6, 17, 5), dark, 0, 8.5, 0);
    mesh(tower, new THREE.BoxGeometry(3.2, 0.4, 1.2), dark, 0, 17.1, 0);
    for (let i = -1; i <= 1; i++) mesh(tower, new THREE.CylinderGeometry(0.24, 0.24, 0.26, 8), amber, i * 1.05, 16.8, 0.45, Math.PI / 2);
    group.add(tower);
    world.addCircleCollider(x, z, 0.8, 'tower');
  }

  // Tents.
  const tentPositions = [
    [-68, 54, fabricRed], [64, 60, fabricCream], [-72, -8, fabricCream],
    [72, -6, fabricRed], [-94, 90, fabricRed], [92, 92, fabricCream],
  ];
  for (const [x, z, fabric] of tentPositions) {
    const y = world.heightAt(x, z);
    const tent = new THREE.Group();
    tent.position.set(x, y, z);
    mesh(tent, new THREE.BoxGeometry(13, 0.25, 10), concrete, 0, 0.12, 0);
    mesh(tent, new THREE.ConeGeometry(8.6, 5.2, 4), fabric, 0, 5.4, 0, 0, Math.PI / 4);
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) mesh(tent, new THREE.CylinderGeometry(0.12, 0.12, 4.2, 5), dark, sx * 5.4, 2.1, sz * 4.1);
    group.add(tent);
  }

  // Barrier fence around the plinth.
  const barrierMat = new THREE.MeshStandardMaterial({ color: 0xb8b9b5, roughness: 0.55, metalness: 0.55 });
  for (let i = 0; i < 28; i++) {
    const a = (i / 28) * Math.PI * 2;
    const x = Math.cos(a) * 24;
    const z = 10 + Math.sin(a) * 24;
    if (z < -7) continue;
    const barrier = new THREE.Group();
    barrier.position.set(x, world.heightAt(x, z), z);
    barrier.rotation.y = -a;
    mesh(barrier, new THREE.BoxGeometry(4.2, 0.12, 0.08), barrierMat, 0, 1.05, 0);
    mesh(barrier, new THREE.BoxGeometry(4.2, 0.08, 0.08), barrierMat, 0, 0.55, 0);
    mesh(barrier, new THREE.BoxGeometry(0.08, 1.2, 0.08), barrierMat, -2, 0.6, 0);
    mesh(barrier, new THREE.BoxGeometry(0.08, 1.2, 0.08), barrierMat, 2, 0.6, 0);
    group.add(barrier);
  }

  // Flags.
  const flagMatA = new THREE.MeshStandardMaterial({ color: 0xff5a2a, side: THREE.DoubleSide, roughness: 0.7 });
  const flagMatB = new THREE.MeshStandardMaterial({ color: 0xffbe3d, side: THREE.DoubleSide, roughness: 0.7 });
  for (let i = 0; i < 14; i++) {
    const x = -100 + i * 15.4;
    const z = 140 - Math.abs(i - 7) * 8;
    const y = world.heightAt(x, z);
    const pole = new THREE.Group();
    pole.position.set(x, y, z);
    mesh(pole, new THREE.CylinderGeometry(0.07, 0.09, 8, 5), barrierMat, 0, 4, 0);
    const flag = mesh(pole, new THREE.PlaneGeometry(2.8, 1.4), i % 2 ? flagMatA : flagMatB, 1.35, 7.2, 0);
    flag.castShadow = false;
    pole.userData.baseY = y;
    group.add(pole);
    world.flags.push(flag);
  }

  // Start / finish gate on the circuit.
  buildStartGate(world, group);

  // A few low fences along the festival approach.
  for (const side of [-1, 1]) {
    for (let i = 0; i < 10; i++) {
      const x = side * (30 + i * 7.5);
      const z = 138 + i * 4;
      const y = world.heightAt(x, z);
      const fence = new THREE.Group();
      fence.position.set(x, y, z);
      fence.rotation.y = side * 0.2;
      mesh(fence, new THREE.BoxGeometry(7.6, 0.12, 0.08), barrierMat, 0, 1, 0);
      mesh(fence, new THREE.BoxGeometry(0.08, 1.1, 0.08), barrierMat, -3.7, 0.55, 0);
      mesh(fence, new THREE.BoxGeometry(0.08, 1.1, 0.08), barrierMat, 3.7, 0.55, 0);
      group.add(fence);
    }
  }
}

function buildStartGate(world, parent) {
  const path = world.roadPaths.find((p) => p.id === 'circuit');
  if (!path) return;
  const sample = path.samples[0];
  const yaw = Math.atan2(sample.tx, sample.tz);
  const ground = world.heightAt(sample.x, sample.z);
  const group = new THREE.Group();
  group.position.set(sample.x, ground, sample.z);
  group.rotation.y = yaw;
  parent.add(group);

  const metal = new THREE.MeshStandardMaterial({ color: 0x1a1d22, roughness: 0.5, metalness: 0.65 });
  const white = new THREE.MeshStandardMaterial({ color: 0xf2eee3, roughness: 0.7 });
  const banner = new THREE.MeshBasicMaterial({ map: makeBannerTexture('START / FINISH', 'HORIZON CIRCUIT'), toneMapped: false });
  for (const side of [-1, 1]) {
    mesh(group, new THREE.BoxGeometry(1.1, 11, 1.1), metal, side * 13.5, 5.5, 0);
    mesh(group, new THREE.BoxGeometry(2.2, 0.3, 2.2), metal, side * 13.5, 0.15, 0);
  }
  mesh(group, new THREE.BoxGeometry(29, 3.6, 0.35), metal, 0, 10, 0);
  const plane = mesh(group, new THREE.PlaneGeometry(28, 3.3), banner, 0, 10, 0.2);
  plane.castShadow = false;

  const check = new THREE.MeshBasicMaterial({ map: makeCheckeredTexture(), toneMapped: false });
  const line = new THREE.Mesh(new THREE.PlaneGeometry(path.width, 3.2), check);
  line.rotation.x = -Math.PI / 2;
  line.position.set(0, 0.08, 0);
  group.add(line);

  // Finish gate glow.
  const glowTex = makeGlowTexture('rgba(255,190,61,1)', 'rgba(255,90,42,0)');
  const glowMat = new THREE.SpriteMaterial({ map: glowTex, transparent: true, opacity: 0.34, blending: THREE.AdditiveBlending, depthWrite: false });
  for (const side of [-1, 1]) {
    const sprite = new THREE.Sprite(glowMat);
    sprite.scale.set(6, 6, 1);
    sprite.position.set(side * 13.5, 5.5, 0.5);
    group.add(sprite);
  }
  world.startGate = { x: sample.x, z: sample.z, yaw };
}

import * as THREE from 'three';
import { CITY, FESTIVAL, LAKE } from '../config.js';
import { clamp, fbm, mulberry32, TAU, makeCanvas } from '../utils.js';
import { makeCloudTexture, makeGlowTexture, makeSignTexture } from './textures.js';

function matrixAt(x, y, z, scale, rotY) {
  const m = new THREE.Matrix4();
  const q = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), rotY);
  m.compose(new THREE.Vector3(x, y, z), q, new THREE.Vector3(scale, scale, scale));
  return m;
}

export function buildNature(world) {
  buildTrees(world);
  buildRocks(world);
  buildFarms(world);
  buildTurbines(world);
  buildLakeProps(world);
  buildClouds(world);
  buildBalloons(world);
  buildBlimp(world);
}

function buildTrees(world) {
  const rand = mulberry32(512);
  const target = world.quality.trees || 620;
  const trees = [];
  let attempts = 0;
  while (trees.length < target && attempts < target * 9) {
    attempts++;
    const x = (rand() - 0.5) * 3600;
    const z = (rand() - 0.5) * 3600;
    const cityD = Math.hypot(x - CITY.x, z - CITY.z);
    const festD = Math.hypot(x - FESTIVAL.x, z - FESTIVAL.z);
    if (cityD < CITY.radius + 25 || festD < 265) continue;
    const road = world.sampleRoadField(x, z);
    if (road.dist < 17) continue;
    const y = world.heightAt(x, z);
    if (y < 3.4 || y > 82) continue;
    if (world.slopeAt(x, z) > 0.58) continue;
    const density = fbm(x * 0.00125 + 2, z * 0.00125 - 1, 3, 5);
    if (rand() > 0.18 + density * 1.3) continue;
    const lakeD = Math.hypot(x - LAKE.x, z - LAKE.z);
    if (lakeD < LAKE.radius + 18) continue;
    trees.push({
      x, y, z,
      scale: 0.68 + rand() * 0.85,
      rot: rand() * TAU,
      type: rand() > 0.3 ? 'pine' : 'oak',
      shade: rand(),
    });
  }

  const pines = trees.filter((t) => t.type === 'pine');
  const oaks = trees.filter((t) => t.type === 'oak');
  const trunkGeo = new THREE.CylinderGeometry(0.25, 0.44, 3.4, 5);
  trunkGeo.translate(0, 1.7, 0);
  const trunkMat = new THREE.MeshStandardMaterial({ color: 0x5a4432, roughness: 1 });
  const trunkMesh = new THREE.InstancedMesh(trunkGeo, trunkMat, trees.length);
  trunkMesh.castShadow = world.quality.shadows;
  trunkMesh.receiveShadow = true;
  const trunkColor = new THREE.Color();

  const pineMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.92, flatShading: true });
  const pineGeo = new THREE.ConeGeometry(2.7, 6.4, 7);
  pineGeo.translate(0, 4.6, 0);
  const pineGeo2 = new THREE.ConeGeometry(1.9, 4.5, 7);
  pineGeo2.translate(0, 7.3, 0);
  const pineMesh = new THREE.InstancedMesh(pineGeo, pineMat, pines.length);
  const pineMesh2 = new THREE.InstancedMesh(pineGeo2, pineMat, pines.length);
  pineMesh.castShadow = world.quality.shadows;
  pineMesh2.castShadow = world.quality.shadows;
  pineMesh.receiveShadow = true;
  pineMesh2.receiveShadow = true;

  const oakMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.94, flatShading: true });
  const oakGeo = new THREE.IcosahedronGeometry(2.8, 0);
  oakGeo.translate(0, 5.3, 0);
  const oakMesh = new THREE.InstancedMesh(oakGeo, oakMat, oaks.length);
  oakMesh.castShadow = world.quality.shadows;
  oakMesh.receiveShadow = true;

  let ti = 0;
  let pi = 0;
  let oi = 0;
  const greenA = new THREE.Color(0x385b34);
  const greenB = new THREE.Color(0x4e733c);
  const greenC = new THREE.Color(0x2e4d33);
  for (const tree of trees) {
    const m = matrixAt(tree.x, tree.y, tree.z, tree.scale, tree.rot);
    trunkMesh.setMatrixAt(ti, m);
    trunkColor.setHex(0x5a4432).offsetHSL(0, 0, (tree.shade - 0.5) * 0.12);
    trunkMesh.setColorAt(ti, trunkColor);
    ti++;
    if (tree.type === 'pine') {
      pineMesh.setMatrixAt(pi, m);
      pineMesh2.setMatrixAt(pi, m);
      const c = greenA.clone().lerp(greenC, tree.shade);
      pineMesh.setColorAt(pi, c);
      pineMesh2.setColorAt(pi, c.clone().offsetHSL(0, 0.02, 0.03));
      pi++;
    } else {
      oakMesh.setMatrixAt(oi, m);
      const c = greenB.clone().lerp(greenA, tree.shade);
      oakMesh.setColorAt(oi, c);
      oi++;
    }
    world.addCircleCollider(tree.x, tree.z, 0.9 * tree.scale, 'tree');
  }
  trunkMesh.instanceMatrix.needsUpdate = true;
  pineMesh.instanceMatrix.needsUpdate = true;
  pineMesh2.instanceMatrix.needsUpdate = true;
  oakMesh.instanceMatrix.needsUpdate = true;
  trunkMesh.computeBoundingSphere();
  pineMesh.computeBoundingSphere();
  pineMesh2.computeBoundingSphere();
  oakMesh.computeBoundingSphere();
  world.scene.add(trunkMesh, pineMesh, pineMesh2, oakMesh);
  world.trees = trees;
}

function buildRocks(world) {
  const rand = mulberry32(228);
  const rocks = [];
  for (let i = 0; i < 210; i++) {
    const x = (rand() - 0.5) * 3700;
    const z = (rand() - 0.5) * 3700;
    if (Math.hypot(x - CITY.x, z - CITY.z) < CITY.radius + 10) continue;
    if (Math.hypot(x - FESTIVAL.x, z - FESTIVAL.z) < 240) continue;
    if (world.sampleRoadField(x, z).dist < 15) continue;
    const y = world.heightAt(x, z);
    if (y < 3) continue;
    rocks.push({ x, y, z, scale: 0.55 + rand() * 2.1, rot: rand() * TAU, shade: rand() });
  }
  const geo = new THREE.DodecahedronGeometry(1, 0);
  const mat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1, flatShading: true });
  const mesh = new THREE.InstancedMesh(geo, mat, rocks.length);
  mesh.castShadow = world.quality.shadows;
  mesh.receiveShadow = true;
  const c = new THREE.Color();
  rocks.forEach((rock, i) => {
    const m = matrixAt(rock.x, rock.y + rock.scale * 0.24, rock.z, rock.scale, rock.rot);
    mesh.setMatrixAt(i, m);
    c.setHex(0x6a675f).offsetHSL(0, 0, (rock.shade - 0.5) * 0.16);
    mesh.setColorAt(i, c);
    if (rock.scale > 1.5) world.addCircleCollider(rock.x, rock.z, rock.scale * 0.75, 'rock');
  });
  mesh.instanceMatrix.needsUpdate = true;
  mesh.computeBoundingSphere();
  world.scene.add(mesh);

  // Low scrub to break up the grass.
  const bushGeo = new THREE.IcosahedronGeometry(0.85, 0);
  const bushMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1, flatShading: true });
  const bushMesh = new THREE.InstancedMesh(bushGeo, bushMat, 320);
  const bc = new THREE.Color();
  for (let i = 0; i < 320; i++) {
    const x = (rand() - 0.5) * 3700;
    const z = (rand() - 0.5) * 3700;
    if (world.sampleRoadField(x, z).dist < 11) continue;
    if (Math.hypot(x - CITY.x, z - CITY.z) < CITY.radius) continue;
    const y = world.heightAt(x, z);
    if (y < 2.8) continue;
    const s = 0.5 + rand() * 1.1;
    bushMesh.setMatrixAt(i, matrixAt(x, y + s * 0.45, z, s, rand() * TAU));
    bc.setHex(0x4b653a).offsetHSL(0, 0, (rand() - 0.5) * 0.15);
    bushMesh.setColorAt(i, bc);
  }
  bushMesh.instanceMatrix.needsUpdate = true;
  bushMesh.computeBoundingSphere();
  world.scene.add(bushMesh);
}

function buildFarms(world) {
  const rand = mulberry32(711);
  const farms = [
    [-920, 220, 0.7], [-1110, 470, -0.4], [-740, -250, 1.3],
    [-1260, -180, 2.1], [420, 880, -0.7], [1030, 780, 1.8],
  ];
  const red = new THREE.MeshStandardMaterial({ color: 0x7f2d25, roughness: 0.9 });
  const cream = new THREE.MeshStandardMaterial({ color: 0xb8aa8a, roughness: 0.94 });
  const roof = new THREE.MeshStandardMaterial({ color: 0x2f3135, roughness: 0.8, metalness: 0.22 });
  const wood = new THREE.MeshStandardMaterial({ color: 0x5a4432, roughness: 1 });
  for (const [x, z, yaw] of farms) {
    if (world.sampleRoadField(x, z).dist < 25) continue;
    const y = world.heightAt(x, z);
    const group = new THREE.Group();
    group.position.set(x, y, z);
    group.rotation.y = yaw;
    const w = 15;
    const h = 7;
    const d = 11;
    const barn = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), red);
    barn.position.y = h / 2;
    barn.castShadow = true;
    barn.receiveShadow = true;
    group.add(barn);
    // Gabled roof.
    const roofA = new THREE.Mesh(new THREE.BoxGeometry(w * 0.6, 0.45, d + 1.4), roof);
    roofA.position.set(-w * 0.24, h + 1.3, 0);
    roofA.rotation.z = 0.52;
    group.add(roofA);
    const roofB = roofA.clone();
    roofB.position.x = w * 0.24;
    roofB.rotation.z = -0.52;
    group.add(roofB);
    const door = new THREE.Mesh(new THREE.BoxGeometry(4.2, 4.8, 0.2), wood);
    door.position.set(0, 2.4, d / 2 + 0.1);
    group.add(door);
    // Silo.
    const silo = new THREE.Mesh(new THREE.CylinderGeometry(2.2, 2.4, 11, 10), cream);
    silo.position.set(w * 0.8, 5.5, -2);
    silo.castShadow = true;
    group.add(silo);
    const siloTop = new THREE.Mesh(new THREE.ConeGeometry(2.4, 2.2, 10), roof);
    siloTop.position.set(w * 0.8, 12.1, -2);
    group.add(siloTop);
    world.scene.add(group);
    world.addBoxCollider(x, z, w / 2, d / 2, 'building');

    // Fence paddock.
    const fenceMat = new THREE.MeshStandardMaterial({ color: 0x7a6850, roughness: 1 });
    for (let side = 0; side < 4; side++) {
      const len = 34;
      for (let i = 0; i < 7; i++) {
        const t = i / 6 - 0.5;
        const px = side < 2 ? t * len : (side === 2 ? -len / 2 : len / 2);
        const pz = side < 2 ? (side === 0 ? -len / 2 : len / 2) : t * len;
        const post = new THREE.Mesh(new THREE.BoxGeometry(0.2, 1.5, 0.2), fenceMat);
        post.position.set(px + (rand() - 0.5) * 0.3, 0.75, pz);
        group.add(post);
      }
    }
    // Hay bales.
    for (let i = 0; i < 3; i++) {
      const bale = new THREE.Mesh(new THREE.CylinderGeometry(1.2, 1.2, 1.8, 10), new THREE.MeshStandardMaterial({ color: 0xb69755, roughness: 1 }));
      bale.rotation.z = Math.PI / 2;
      bale.position.set(-w * 0.65 + rand() * 3, 1.2, 7 + rand() * 2);
      group.add(bale);
    }
  }
}

function buildTurbines(world) {
  const positions = [
    [-1140, 980], [-820, 1220], [280, 1280], [980, 1200], [1450, 620],
    [1280, -120], [-1460, -640], [-980, -1180],
  ];
  const white = new THREE.MeshStandardMaterial({ color: 0xe8e8e2, roughness: 0.6, metalness: 0.25 });
  const dark = new THREE.MeshStandardMaterial({ color: 0x262a2e, roughness: 0.5, metalness: 0.5 });
  for (const [x, z] of positions) {
    const y = world.heightAt(x, z);
    if (y < 8) continue;
    const group = new THREE.Group();
    group.position.set(x, y, z);
    const tower = new THREE.Mesh(new THREE.CylinderGeometry(0.7, 1.8, 52, 7), white);
    tower.position.y = 26;
    tower.castShadow = true;
    group.add(tower);
    const nacelle = new THREE.Mesh(new THREE.BoxGeometry(4.5, 2.4, 2.2), white);
    nacelle.position.y = 52.5;
    group.add(nacelle);
    const blades = new THREE.Group();
    blades.position.set(0, 52.5, 2.2);
    for (let i = 0; i < 3; i++) {
      const blade = new THREE.Mesh(new THREE.BoxGeometry(0.75, 25, 0.28), white);
      blade.position.y = 12.5;
      blade.rotation.z = (i / 3) * TAU;
      const holder = new THREE.Group();
      holder.rotation.z = (i / 3) * TAU;
      holder.add(blade);
      blades.add(holder);
    }
    const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.8, 0.8, 1.2, 10), dark);
    hub.rotation.x = Math.PI / 2;
    hub.position.z = 0.2;
    blades.add(hub);
    group.add(blades);
    world.scene.add(group);
    world.turbines.push({ group, blades, speed: 0.28 + Math.random() * 0.2 });
    world.addCircleCollider(x, z, 2, 'turbine');
  }
}

function buildLakeProps(world) {
  const wood = new THREE.MeshStandardMaterial({ color: 0x6b5138, roughness: 0.96 });
  const darkWood = new THREE.MeshStandardMaterial({ color: 0x3f3024, roughness: 1 });
  // Dock on the eastern shore, reaching toward the lake centre.
  const shoreX = LAKE.x + LAKE.radius - 4;
  const shoreZ = LAKE.z + 16;
  const ground = world.heightAt(shoreX, shoreZ);
  const dock = new THREE.Group();
  dock.position.set(shoreX, Math.max(WATER_LEVEL + 0.25, ground + 0.12), shoreZ);
  dock.rotation.y = Math.PI / 2;
  for (let i = 0; i < 12; i++) {
    const plank = new THREE.Mesh(new THREE.BoxGeometry(3.4, 0.16, 2.3), i % 2 ? wood : darkWood);
    plank.position.set(0, 0.1, -i * 2.35);
    plank.castShadow = true;
    dock.add(plank);
  }
  for (const side of [-1, 1]) {
    for (let i = 0; i < 5; i++) {
      const post = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.16, 3.2, 6), darkWood);
      post.position.set(side * 1.5, -1.2, -i * 5.2);
      dock.add(post);
    }
  }
  world.scene.add(dock);

  // Little sailboats.
  const hullMat = new THREE.MeshStandardMaterial({ color: 0xe8e4d8, roughness: 0.6 });
  const hullMat2 = new THREE.MeshStandardMaterial({ color: 0xff5a2a, roughness: 0.7 });
  const sailMat = new THREE.MeshStandardMaterial({ color: 0xf2efe4, roughness: 0.8, side: THREE.DoubleSide });
  for (let i = 0; i < 4; i++) {
    const a = i * 1.7 + 0.5;
    const r = 90 + i * 52;
    const boat = new THREE.Group();
    boat.position.set(LAKE.x + Math.cos(a) * r, WATER_LEVEL + 0.25, LAKE.z + Math.sin(a) * r);
    boat.rotation.y = a + 0.8;
    const hull = new THREE.Mesh(new THREE.BoxGeometry(5.5, 1.1, 2.1), i % 2 ? hullMat : hullMat2);
    hull.position.y = 0.4;
    boat.add(hull);
    const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.1, 8, 5), darkWood);
    mast.position.y = 4.6;
    boat.add(mast);
    const sail = new THREE.Mesh(new THREE.PlaneGeometry(3.4, 5.4), sailMat);
    sail.position.set(1.2, 5.1, 0);
    sail.rotation.y = Math.PI / 2;
    boat.add(sail);
    boat.userData.baseY = boat.position.y;
    boat.userData.bob = 0.12;
    boat.userData.bobSpeed = 0.8 + i * 0.17;
    boat.userData.phase = i * 1.4;
    world.scene.add(boat);
    world.boats.push(boat);
    world.animated.push(boat);
  }

  // Reeds at the shoreline.
  const reedGeo = new THREE.ConeGeometry(0.08, 1.8, 4);
  const reedMat = new THREE.MeshStandardMaterial({ color: 0x6f7a3b, roughness: 1 });
  const reedMesh = new THREE.InstancedMesh(reedGeo, reedMat, 160);
  for (let i = 0; i < 160; i++) {
    const a = i * 2.399;
    const r = LAKE.radius - 8 + Math.sin(i) * 6;
    const x = LAKE.x + Math.cos(a) * r;
    const z = LAKE.z + Math.sin(a) * r;
    const y = world.heightAt(x, z);
    reedMesh.setMatrixAt(i, matrixAt(x, y + 0.9, z, 0.8 + (i % 5) * 0.08, a));
  }
  reedMesh.instanceMatrix.needsUpdate = true;
  world.scene.add(reedMesh);
}

function buildClouds(world) {
