import { clamp } from './utils.js';

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.ready = false;
    this.enabled = true;
    this.volume = 0.65;
    this.engineGain = null;
    this.windGain = null;
    this.tireGain = null;
    this.osc = [];
    this.filter = null;
    this.noiseBuffer = null;
    this.tireFilter = null;
    this.windFilter = null;
    this.started = false;
  }

  async init() {
    if (this.ready) {
      await this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    const ctx = this.ctx;
    this.master = ctx.createGain();
    this.master.gain.value = this.enabled ? this.volume : 0;
    this.master.connect(ctx.destination);

    // Shared noise source for wind and tire scrub.
    const length = ctx.sampleRate * 2;
    const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < length; i++) {
      const white = Math.random() * 2 - 1;
      last = last * 0.86 + white * 0.14;
      data[i] = last * 1.4;
    }
    this.noiseBuffer = buffer;

    this.engineGain = ctx.createGain();
    this.engineGain.gain.value = 0;
    this.filter = ctx.createBiquadFilter();
    this.filter.type = 'lowpass';
    this.filter.frequency.value = 420;
    this.filter.Q.value = 1.4;
    this.engineGain.connect(this.filter);
    this.filter.connect(this.master);

    const makeOsc = (type, freq, detune = 0, gain = 0.3) => {
      const osc = ctx.createOscillator();
      const g = ctx.createGain();
      osc.type = type;
      osc.frequency.value = freq;
      osc.detune.value = detune;
      g.gain.value = gain;
      osc.connect(g);
      g.connect(this.engineGain);
      osc.start();
      this.osc.push({ osc, gain: g });
      return osc;
    };
    makeOsc('sawtooth', 70, -4, 0.32);
    makeOsc('square', 140, 5, 0.12);
    makeOsc('sine', 35, 0, 0.5);

    const windSource = ctx.createBufferSource();
    windSource.buffer = buffer;
    windSource.loop = true;
    this.windGain = ctx.createGain();
    this.windGain.gain.value = 0;
    this.windFilter = ctx.createBiquadFilter();
    this.windFilter.type = 'lowpass';
    this.windFilter.frequency.value = 500;
    windSource.connect(this.windFilter);
    this.windFilter.connect(this.windGain);
    this.windGain.connect(this.master);
    windSource.start();

    const tireSource = ctx.createBufferSource();
    tireSource.buffer = buffer;
    tireSource.loop = true;
    this.tireGain = ctx.createGain();
    this.tireGain.gain.value = 0;
    this.tireFilter = ctx.createBiquadFilter();
    this.tireFilter.type = 'bandpass';
    this.tireFilter.frequency.value = 2100;
    this.tireFilter.Q.value = 1.2;
    tireSource.connect(this.tireFilter);
    this.tireFilter.connect(this.tireGain);
    this.tireGain.connect(this.master);
    tireSource.start();

    this.ready = true;
    await ctx.resume();
  }

  setEnabled(enabled) {
    this.enabled = enabled;
    if (this.master) {
      this.master.gain.setTargetAtTime(enabled ? this.volume : 0, this.ctx.currentTime, 0.05);
    }
  }

  setVolume(volume) {
    this.volume = clamp(volume, 0, 1);
    if (this.master) this.master.gain.setTargetAtTime(this.enabled ? this.volume : 0, this.ctx.currentTime, 0.04);
  }

  update(vehicle, paused = false) {
    if (!this.ready || !vehicle) return;
    const now = this.ctx.currentTime;
    if (paused) {
      this.engineGain.gain.setTargetAtTime(0.0001, now, 0.08);
      this.windGain.gain.setTargetAtTime(0.0001, now, 0.08);
      this.tireGain.gain.setTargetAtTime(0.0001, now, 0.08);
      return;
    }
    const rpmNorm = clamp((vehicle.rpm - 800) / 5800, 0, 1.15);
    const speedNorm = clamp(vehicle.speedKmh / 360, 0, 1.2);
    const electric = vehicle.config.engine?.cylinders === 0;
    const base = electric ? 90 + rpmNorm * 460 : 32 + rpmNorm * 150;
    this.osc[0].osc.frequency.setTargetAtTime(base, now, 0.035);
    this.osc[1].osc.frequency.setTargetAtTime(base * (electric ? 2.9 : 2.02), now, 0.035);
    this.osc[2].osc.frequency.setTargetAtTime(base * 0.5, now, 0.045);
    this.filter.frequency.setTargetAtTime(260 + rpmNorm * (electric ? 2400 : 1500) + Math.abs(vehicle.throttle) * 280, now, 0.05);
    this.filter.Q.setTargetAtTime(1.1 + rpmNorm * 1.8, now, 0.1);
    const engineLevel = 0.018 + Math.abs(vehicle.throttle) * 0.032 + speedNorm * 0.014 + (vehicle.airborne ? 0.004 : 0);
    this.engineGain.gain.setTargetAtTime(engineLevel, now, 0.06);
    this.windGain.gain.setTargetAtTime(0.002 + speedNorm * 0.055, now, 0.1);
    this.windFilter.frequency.setTargetAtTime(300 + speedNorm * 1500, now, 0.1);
    const slip = vehicle.drifting ? 0.03 + clamp(vehicle.slip / 20, 0, 1) * 0.045 : (vehicle.onRoad ? 0.0015 : 0.008);
    this.tireGain.gain.setTargetAtTime(slip, now, 0.06);
    this.tireFilter.frequency.setTargetAtTime(1500 + speedNorm * 1300, now, 0.08);
  }

  click() {
    if (!this.ready) return;
    const ctx = this.ctx;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(760, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(320, ctx.currentTime + 0.08);
    gain.gain.setValueAtTime(0.045, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.09);
    osc.connect(gain);
    gain.connect(this.master);
    osc.start();
    osc.stop(ctx.currentTime + 0.1);
  }

  beep(frequency = 560, duration = 0.14, volume = 0.05) {
    if (!this.ready) return;
    const ctx = this.ctx;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.value = frequency;
    gain.gain.setValueAtTime(volume, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + duration);
    osc.connect(gain);
    gain.connect(this.master);
    osc.start();
    osc.stop(ctx.currentTime + duration + 0.02);
  }

  chord(frequencies, duration = 0.4) {
    if (!this.ready) return;
    frequencies.forEach((f, i) => setTimeout(() => this.beep(f, duration, 0.04), i * 70));
  }
}

import * as THREE from 'three';
import { clamp } from './utils.js';

function softDotTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.45, 'rgba(255,255,255,.55)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 128, 128);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

const MAX_PARTICLES = 700;

export class Effects {
  constructor(scene) {
    this.scene = scene;
    this.particles = [];
    this.cursor = 0;
    this.skidCursor = 0;
    this.skidTimer = 0;

    const positions = new Float32Array(MAX_PARTICLES * 3);
    const colors = new Float32Array(MAX_PARTICLES * 3);
    const sizes = new Float32Array(MAX_PARTICLES);
    const alphas = new Float32Array(MAX_PARTICLES);
    for (let i = 0; i < MAX_PARTICLES; i++) {
      this.particles.push({ life: 0, maxLife: 1, vx: 0, vy: 0, vz: 0, drag: 0.95, gravity: 0, grow: 0 });
    }
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    geometry.setAttribute('aSize', new THREE.BufferAttribute(sizes, 1));
    geometry.setAttribute('aAlpha', new THREE.BufferAttribute(alphas, 1));
    this.geometry = geometry;
    const material = new THREE.ShaderMaterial({
      uniforms: { uMap: { value: softDotTexture() } },
      vertexShader: `
        attribute float aSize;
        attribute float aAlpha;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vColor = color;
          vAlpha = aAlpha;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = aSize * (340.0 / max(1.0, -mv.z));
          gl_Position = projectionMatrix * mv;
        }
      `,
      fragmentShader: `
        uniform sampler2D uMap;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          float mask = texture2D(uMap, gl_PointCoord).a;
          if (mask < 0.01) discard;
          gl_FragColor = vec4(vColor, mask * vAlpha);
        }
      `,
      transparent: true,
      depthWrite: false,
      vertexColors: true,
      blending: THREE.NormalBlending,
    });
    this.points = new THREE.Points(geometry, material);
    this.points.frustumCulled = false;
    this.points.renderOrder = 5;
    scene.add(this.points);

    // Skid marks.
    const skidGeo = new THREE.PlaneGeometry(0.42, 1.9);
    skidGeo.rotateX(-Math.PI / 2);
    this.skidMaterial = new THREE.MeshBasicMaterial({
      color: 0x0a0907,
      transparent: true,
      opacity: 0.34,
      depthWrite: false,
      polygonOffset: true,
      polygonOffsetFactor: -4,
      polygonOffsetUnits: -4,
    });
    this.skidPool = [];
    for (let i = 0; i < 150; i++) {
      const mark = new THREE.Mesh(skidGeo, this.skidMaterial);
      mark.visible = false;
      mark.renderOrder = 2;
      scene.add(mark);
      this.skidPool.push(mark);
    }
  }

  spawn(x, y, z, options = {}) {
    const p = this.particles[this.cursor];
    const index = this.cursor;
    this.cursor = (this.cursor + 1) % MAX_PARTICLES;
    const life = options.life ?? 0.8;
    p.life = life;
    p.maxLife = life;
    p.vx = options.vx ?? 0;
    p.vy = options.vy ?? 0.5;
    p.vz = options.vz ?? 0;
    p.drag = options.drag ?? 0.93;
    p.gravity = options.gravity ?? -0.4;
    p.grow = options.grow ?? 1;
    p.size = options.size ?? 1;
    p.baseSize = p.size;
    const color = options.color ?? new THREE.Color(0xd8c6a0);
    this.geometry.attributes.position.setXYZ(index, x, y, z);
    this.geometry.attributes.color.setXYZ(index, color.r, color.g, color.b);
    this.geometry.attributes.aSize.setX(index, p.size);
    this.geometry.attributes.aAlpha.setX(index, options.alpha ?? 0.8);
  }

  burst(position, color, count = 18, power = 5, up = 3) {
    const c = new THREE.Color(color);
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2;
      const r = Math.random() * power;
      this.spawn(position.x, position.y, position.z, {
        vx: Math.cos(a) * r,
        vy: Math.random() * up + 0.5,
        vz: Math.sin(a) * r,
        color: c.clone().offsetHSL(0, 0, (Math.random() - 0.5) * 0.2),
        size: 0.3 + Math.random() * 0.7,
        life: 0.6 + Math.random() * 0.9,
        gravity: -5,
        drag: 0.965,
      });
    }
  }

  dust(position, color = 0xb7a178, count = 2, speed = 2) {
    const c = new THREE.Color(color);
    for (let i = 0; i < count; i++) {
      this.spawn(position.x + (Math.random() - 0.5) * 1.4, position.y + 0.25, position.z + (Math.random() - 0.5) * 1.4, {
        vx: (Math.random() - 0.5) * speed,
        vy: 0.7 + Math.random() * 1.1,
        vz: (Math.random() - 0.5) * speed,
        color: c.clone().offsetHSL(0, 0, (Math.random() - 0.5) * 0.14),
        size: 0.9 + Math.random() * 1.2,
        life: 0.75 + Math.random() * 0.7,
        gravity: -0.3,
        drag: 0.94,
        alpha: 0.32,
      });
    }
  }

  smoke(position, count = 1) {
    for (let i = 0; i < count; i++) {
      this.spawn(position.x + (Math.random() - 0.5) * 0.8, position.y + 0.2, position.z + (Math.random() - 0.5) * 0.8, {
        vx: (Math.random() - 0.5) * 1.2,
        vy: 0.6 + Math.random() * 0.8,
        vz: (Math.random() - 0.5) * 1.2,
        color: new THREE.Color(0xd9d5ca),
        size: 0.7 + Math.random() * 1.1,
        life: 0.9 + Math.random() * 0.9,
        gravity: 0.1,
        drag: 0.94,
        alpha: 0.2,
      });
    }
  }

  addSkid(x, z, yaw, groundY) {
    const mark = this.skidPool[this.skidCursor];
    this.skidCursor = (this.skidCursor + 1) % this.skidPool.length;
    mark.position.set(x, groundY + 0.035, z);
    mark.rotation.y = yaw;
    mark.visible = true;
    mark.material = this.skidMaterial;
  }

  update(dt) {
    const pos = this.geometry.attributes.position;
    const color = this.geometry.attributes.color;
    const size = this.geometry.attributes.aSize;
    const alpha = this.geometry.attributes.aAlpha;
    for (let i = 0; i < MAX_PARTICLES; i++) {
      const p = this.particles[i];
      if (p.life <= 0) {
        if (alpha.getX(i) !== 0) {
          alpha.setX(i, 0);
          size.setX(i, 0);
        }
        continue;
      }
      p.life -= dt;
      if (p.life <= 0) {
        alpha.setX(i, 0);
        size.setX(i, 0);
        continue;
      }
      const t = p.life / p.maxLife;
      p.vx *= Math.pow(p.drag, dt * 60);
      p.vz *= Math.pow(p.drag, dt * 60);
      p.vy += p.gravity * dt;
      pos.setXYZ(i, pos.getX(i) + p.vx * dt, pos.getY(i) + p.vy * dt, pos.getZ(i) + p.vz * dt);
      size.setX(i, p.baseSize * (1 + (1 - t) * p.grow));
      alpha.setX(i, t * t * 0.9);
    }
    pos.needsUpdate = true;
    size.needsUpdate = true;
    alpha.needsUpdate = true;
    color.needsUpdate = true;
  }

  clearSkids() {
    for (const mark of this.skidPool) mark.visible = false;
  }
}

