  filter: drop-shadow(0 18px 50px rgba(255, 78, 32, .1));
}
.loading-bar { width: 100%; height: 2px; background: rgba(255,255,255,.12); overflow: hidden; }
.loading-bar i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, var(--accent), var(--accent-2)); box-shadow: 0 0 24px var(--accent); transition: width .2s ease; }
.loading-meta { display: flex; justify-content: space-between; margin-top: 10px; font-size: 9px; font-weight: 700; letter-spacing: .16em; color: var(--muted); text-transform: uppercase; }

/* ---------- menu ---------- */
.menu-screen {
  z-index: 20;
  padding: calc(30px + var(--safe-top)) clamp(26px, 4vw, 72px) calc(26px + var(--safe-bottom));
